import subprocess,string
for ch in string.printable.strip():
    if ch in ' \t\n\r\x0b\x0c': continue
    a=f"-lx{ch}y"
    p=subprocess.run(["./executable",a,"/tmp/t/a.txt"],capture_output=True)
