import os
from dataclasses import dataclass, field

BAT_VERSION = "bat 0.26.1 (4dd824a)"

class ClapError(Exception):
    def __init__(self, text, kind="error"):
        super().__init__(text)
        self.text = text
        self.kind = kind
class VersionAction(Exception):
    pass
class CacheHelpAction(Exception):
    def __init__(self, long):
        self.long = long

@dataclass
class Token:
    text: str
    source: str = "cli"

@dataclass
