def jaro(s1, s2):
    if s1 == s2:
        return 1.0
    len1, len2 = len(s1), len(s2)
    if not len1 or not len2:
        return 0.0
    match_dist = max(len1, len2)//2 - 1
    if match_dist < 0:
        match_dist = 0
    s1_matches = [False]*len1
    s2_matches = [False]*len2
    matches = 0
    for i,ch in enumerate(s1):
        start = max(0, i-match_dist)
        end = min(len2, i+match_dist+1)
        for j in range(start,end):
            if not s2_matches[j] and s2[j]==ch:
                s1_matches[i]=True; s2_matches[j]=True; matches+=1; break
    if matches==0:
        return 0.0
    k=0; trans=0
    for i in range(len1):
        if s1_matches[i]:
            while not s2_matches[k]: k+=1
            if s1[i]!=s2[k]: trans+=1
            k+=1
    return (matches/len1 + matches/len2 + (matches-trans//2)/matches)/3

def shell_split(line):
    tokens=[]; cur=''; started=False; quote=None; i=0
    while i < len(line):
        c=line[i]
        if quote == "'":
            if c == "'": quote=None
            else: cur+=c
            i+=1; continue
        if quote == '"':
            if c == '"': quote=None; i+=1; continue
            if c == '\\' and i+1 < len(line) and line[i+1] in '"\\$`':
