class Parser:
    def __init__(self, specs, prog, is_cache=False, conflicts=None):
        self.specs=specs; self.prog=prog; self.is_cache=is_cache
        self.conflicts=conflicts or {}
        self.longmap={}
        self.shortmap={}
        for sp in specs:
            self.longmap[sp.long]=sp
            for a in sp.aliases: self.longmap[a]=sp
            if sp.short: self.shortmap[sp.short]=sp
    # ---------- usage ----------
    def generic_usage(self):
        if self.is_cache:
            return f"Usage: {self.prog} cache [OPTIONS]"
        return f"Usage: {self.prog} [OPTIONS] [FILE]...\n       {self.prog} <COMMAND>"
    def smart_usage(self, used, file_used=False, extra=None, exclude_ids=()):
        # used: list of Spec in encounter order
        items=[]
        seen=set()
        for sp in used:
            if sp.id in seen or sp.id in exclude_ids or sp.hidden:
                continue
            seen.add(sp.id); items.append(sp.usage_display)
        if extra is not None and extra.id not in seen and extra.id not in exclude_ids and not extra.hidden:
            items.append(extra.usage_display)
        if not items:
            return self.generic_usage()
        if self.is_cache:
            return f"Usage: {self.prog} cache " + " ".join(items)
        return f"Usage: {self.prog} " + " ".join(items) + (" <FILE>..." if file_used else " [FILE]...")
    def suffix(self):
        return "\n\nFor more information, try '--help'.\n" if self.is_cache else ""
    # ---------- error builders ----------
    def err_unknown(self, token_display, used, file_used, suggestion=None):
        lines=[f"error: unexpected argument '{token_display}' found", ""]
        if suggestion is not None:
            lines.append(f"  tip: a similar argument exists: '--{suggestion.long}'")
            lines.append("")
            usage=self.smart_usage(used,file_used,extra=suggestion)
        else:
            if not self.is_cache:
                lines.append(f"  tip: to pass '{token_display}' as a value, use '-- {token_display}'")
                lines.append("")
            usage=self.smart_usage(used,file_used) if used else self.generic_usage()
        lines.append(usage)
        txt="\n".join(lines)+"\n"
        if self.is_cache: txt+="\nFor more information, try '--help'.\n"
        raise ClapError(txt)
    def err_missing(self,spec):
        if spec is None:
            raise ClapError("error: a value is required for '[FILE]...' but none was supplied\n")
        txt=f"error: a value is required for '{spec.display}' but none was supplied\n"
        if spec.choices:
            txt+=f"  [possible values: {', '.join(spec.choices)}]\n"
        if self.is_cache: txt+="\nFor more information, try '--help'.\n"
        raise ClapError(txt)
    def err_invalid(self,spec,value):
        txt=f"error: invalid value '{value}' for '{spec.display}'"
        if spec.choices:
            txt+=f"\n  [possible values: {', '.join(spec.choices)}]\n"
        else:
            # custom messages handled by caller via err_msg/lookup
            txt+="\n"
        if self.is_cache: txt+="\nFor more information, try '--help'.\n"
        raise ClapError(txt)
    def validate_or_raise(self,spec,value):
        try:
            return spec.validate(value)
        except LookupError as e:
            raise ClapError(f"error: invalid value '{value}' for '{spec.display}': Unknown style '{e.args[0]}'\n")
        except ZeroDivisionError:
            raise ClapError(f"error: invalid value '{value}' for '{spec.display}': terminal width cannot be zero\n")
        except Exception:
            if spec.choices:
                self.err_invalid(spec,value)
            msg=spec.err_msg or 'invalid value'
            raise ClapError(f"error: invalid value '{value}' for '{spec.display}': {msg}\n")
    def err_multiple(self,spec):
        txt=f"error: the argument '{spec.display}' cannot be used multiple times\n\n{self.generic_usage()}\n"
        if self.is_cache: txt+="\nFor more information, try '--help'.\n"
        raise ClapError(txt)
    def suggestion_for(self,name):
        best=None; bestscore=0.0
        for cand,sp in self.longmap.items():
            sc=jaro(name,cand)
            if sc>bestscore:
                bestscore=sc; best=sp
        if bestscore>0.8:
            return best
        return None
    def is_recognized_start(self, tok):
        if tok=='--': return True
        if tok.startswith('--'):
            n=tok[2:].split('=',1)[0]
            return n in self.longmap
        if tok.startswith('-') and len(tok)>1:
            return tok[1] in self.shortmap
        return False
    # ---------- parse ----------
    def parse(self,tokens):
        parsed=Parsed()
        seen_count={}
        used=[]  # Specs in encounter order
        file_used=False
        end=False
        idx=0
        occ_index=0
        def register(spec,value,source):
            nonlocal occ_index
            if spec.repeat=='single' and seen_count.get(spec.id,0)>=1:
                self.err_multiple(spec)
            seen_count[spec.id]=seen_count.get(spec.id,0)+1
            parsed.occ.append(Occ(spec.id,value,source,occ_index)); occ_index+=1
            if spec not in used: used.append(spec)
        def register_value(spec,raw,source):
            # repeat check before validation for single
            if spec.repeat=='single' and seen_count.get(spec.id,0)>=1:
                self.err_multiple(spec)
            if spec.disallow_empty and raw=='':
                self.err_missing(spec)
            v=self.validate_or_raise(spec,raw)
            seen_count[spec.id]=seen_count.get(spec.id,0)+1
            nonlocal_occ[0]+=1
            parsed.occ.append(Occ(spec.id,v,source,nonlocal_occ[0]-1))
            if spec not in used: used.append(spec)
        nonlocal_occ=[0]
        # patch register to use nonlocal_occ counter consistently
        def register2(spec,value,source):
            if spec.repeat=='single' and seen_count.get(spec.id,0)>=1:
                self.err_multiple(spec)
            seen_count[spec.id]=seen_count.get(spec.id,0)+1
            parsed.occ.append(Occ(spec.id,value,source,nonlocal_occ[0])); nonlocal_occ[0]+=1
            if spec not in used: used.append(spec)
        register=register2
        register_value_fn=register_value

        i=0
        while i < len(tokens):
            tok=tokens[i]; text=tok.text; src=tok.source
            if not end and text=='--':
                end=True; i+=1; continue
            if not end and text.startswith('--') and len(text)>2:
                body=text[2:]
                if '=' in body:
                    name,eqval=body.split('=',1); has_eq=True
                else:
                    name,eqval,has_eq=body,None,False
                spec=self.longmap.get(name)
                if spec is None:
                    sugg=self.suggestion_for(name)
                    self.err_unknown('--'+name, used, file_used, sugg)
                if spec.kind=='version':
                    if has_eq:
                        raise ClapError(f"error: unexpected value '{eqval}' for '--version' found; no more were expected\n\nUsage: {self.prog} --version [FILE]...\n")
                    raise VersionAction()
                if spec.kind in ('flag','count','help','cachehelp'):
                    if has_eq:
                        u=self.smart_usage(used,file_used,extra=spec)
                        raise ClapError(f"error: unexpected value '{eqval}' for '{spec.display}' found; no more were expected\n\n{u}\n")
                    if spec.kind=='cachehelp':
                        raise CacheHelpAction(long=True)
                    register(spec,True,src)
                    if spec.kind=='help':
                        parsed.help_kind='long'
                    i+=1; continue
                # value option
                if has_eq:
                    register_value_fn(spec,eqval,src); i+=1; continue
                # need next token
                if i+1>=len(tokens):
                    self.err_missing(spec)
                nxt=tokens[i+1].text
                consumable = (nxt=='-' or nxt=='' or not nxt.startswith('-') or spec.allow_hyphen)
                if not consumable:
                    if self.is_recognized_start(nxt):
                        self.err_missing(spec)
                    else:
                        # let next token be processed as unknown in next iteration
                        i+=1; continue
                register_value_fn(spec,nxt,src); i+=2; continue
            if not end and text.startswith('-') and text!='-' and text!='':
                # short cluster
                j=1; consumed_next=False
                while j < len(text):
                    ch=text[j]
                    spec=self.shortmap.get(ch)
                    if spec is None:
                        self.err_unknown('-'+ch, used, file_used, None)
                    if spec.kind=='version':
                        raise VersionAction()
                    if spec.kind in ('flag','count','help','cachehelp'):
                        if spec.kind=='cachehelp':
                            raise CacheHelpAction(long=False)
                        register(spec,True,src)
                        if spec.kind=='help':
                            parsed.help_kind='short'
                        j+=1; continue
                    # value short
                    rest=text[j+1:]
                    if rest:
                        val=rest[1:] if rest.startswith('=') else rest
                        register_value_fn(spec,val,src)
                    else:
                        if i+1>=len(tokens):
                            self.err_missing(spec)
                        nxt=tokens[i+1].text
                        consumable = (nxt=='-' or nxt=='' or not nxt.startswith('-') or spec.allow_hyphen)
                        if not consumable:
                            if self.is_recognized_start(nxt):
                                self.err_missing(spec)
                            else:
                                consumed_next=False
                                # skip this whole cluster without registering value spec; next iter processes unknown
                                i+=1
                                break
                        register_value_fn(spec,nxt,src); consumed_next=True
                    break
                else:
                    pass
                i+= (2 if consumed_next else 1); continue
            # positional
            if self.is_cache:
                self.err_unknown(text, used, file_used, None)
            if text=='':
                self.err_missing(None)
            parsed.files.append(text); file_used=True; i+=1; continue
        # post parse: conflicts
        if self.conflicts:
            first_ids=[]
            for o in parsed.occ:
                if o.id not in first_ids: first_ids.append(o.id)
            spec_by_id={sp.id:sp for sp in self.specs}
            for sid in first_ids:
                bad=[x for x in first_ids if x in self.conflicts.get(sid,())]
                if bad:
                    sp=spec_by_id[sid]
                    if len(bad)==1:
                        bsp=spec_by_id[bad[0]]
                        txt=f"error: the argument '{sp.display}' cannot be used with '{bsp.display}'\n"
                    else:
                        txt=f"error: the argument '{sp.display}' cannot be used with:\n" + "".join(f"  --{spec_by_id[b].long}\n" for b in bad)
                    usage=self.smart_usage(used,file_used,exclude_ids=set(bad))
                    txt+=f"\n{usage}\n"
                    if self.is_cache: txt+="\nFor more information, try '--help'.\n"
                    raise ClapError(txt)
        if self.is_cache:
            ids={o.id for o in parsed.occ}
            if 'build' not in ids and 'clear' not in ids:
                aux=[sp for sp in used if sp.id in ('source','target','blank','acknowledgements')]
                if aux:
                    bsp=[sp for sp in self.specs if sp.id=='build'][0]
                    usage=self.smart_usage(aux,False,extra=bsp)
                    # smart usage should have build first as in clap: "cache --build --source <dir>"
                    items=" ".join(['--build']+[sp.usage_display for sp in aux])
                    usage=f"Usage: {self.prog} cache {items}"
                    raise ClapError(f"error: the following required arguments were not provided:\n  --build\n\n{usage}\n\nFor more information, try '--help'.\n")
                # no args: handled by caller with kind help2
                raise ClapError("__CACHE_NOARGS__",kind="cache_noargs")
        return parsed

