def jaro(s1, s2):
    if s1 == s2:
        return 1.0
    len1, len2 = len(s1), len(s2)
    if not len1 or not len2:
        return 0.0
    match_dist = max(len1, len2)//2 - 1
    if match_dist < 0:
        match_dist = 0
    s1_matches = [False]*len1
    s2_matches = [False]*len2
    matches = 0
    for i,ch in enumerate(s1):
        start = max(0, i-match_dist)
        end = min(len2, i+match_dist+1)
        for j in range(start,end):
            if not s2_matches[j] and s2[j]==ch:
                s1_matches[i]=True; s2_matches[j]=True; matches+=1; break
    if matches==0:
        return 0.0
    k=0; trans=0
    for i in range(len1):
        if s1_matches[i]:
            while not s2_matches[k]: k+=1
            if s1[i]!=s2[k]: trans+=1
            k+=1
    return (matches/len1 + matches/len2 + (matches-trans//2)/matches)/3

def shell_split(line):
    tokens=[]; cur=''; started=False; quote=None; i=0
    while i < len(line):
        c=line[i]
        if quote == "'":
            if c == "'": quote=None
            else: cur+=c
            i+=1; continue
        if quote == '"':
            if c == '"': quote=None; i+=1; continue
            if c == '\\' and i+1 < len(line) and line[i+1] in '"\\$`':
                cur+=line[i+1]; i+=2; continue
            cur+=c; i+=1; continue
        # unquoted
        if c in ' \t\r\n':
            if started:
                tokens.append(cur); cur=''; started=False
            i+=1; continue
        if c == '#' and not started:
            break
        if c == "'":
            quote="'"; started=True; i+=1; continue
        if c == '"':
            quote='"'; started=True; i+=1; continue
        if c == '\\':
            started=True
            if i+1 < len(line):
                cur+=line[i+1]; i+=2
            else:
                cur+='\\'; i+=1
            continue
        started=True; cur+=c; i+=1
    if quote is not None:
        raise ValueError("unterminated quote")
    if started:
        tokens.append(cur)
    return tokens

def parse_rust_unsigned(s, bits):
    if isinstance(s,str) and s.startswith('+'):
        body=s[1:]
    else:
        body=s
    if not body or not body.isascii() or not body.isdigit():
        raise ValueError(s)
    v=int(body)
    if v > (1<<bits)-1:
        raise ValueError(s)
    return v

def parse_rust_signed(s,bits):
    body=s
    neg=False
    if body.startswith(('+','-')):
        neg=body[0]=='-'; body=body[1:]
    if not body or not body.isascii() or not body.isdigit():
        raise ValueError(s)
    v=int(body)
    if neg: v=-v
    if v < -(1<<(bits-1)) or v > (1<<(bits-1))-1:
        raise ValueError(s)
    return v

STYLE_NAMES={"default","auto","full","plain","changes","header","header-filename","header-filesize","grid","rule","numbers","snip"}
def val_tabs(s):
    return parse_rust_unsigned(s,32)
def val_usize(s):
    return parse_rust_unsigned(s,64)
def val_termwidth(s):
    # returns ('offset',n) or ('abs',n)
    if s[:1] in ('+','-'):
        return ('offset', parse_rust_signed(s,32))
    v=parse_rust_signed(s,32)
    if v==0:
        raise ZeroDivisionError("zero")
    if v<0:
        raise ValueError(s)
    return ('abs',v)
def val_style(s):
    for comp in s.split(','):
        name=comp[1:] if comp[:1] in ('+','-') else comp
        if name not in STYLE_NAMES:
            raise LookupError(name)
    return s

