        # ignored suffix stripping: while current extension (after last dot in basename) matches a suffix '.ext'
        if ignored_suffixes:
            p=path
            while True:
                base=os.path.basename(p)
                if '.' not in base: break
                ext='.'+base.rsplit('.',1)[1]
                if ext in ignored_suffixes:
                    p=p[:len(p)-len(ext)]
                else:
