def _default_slots():
    # Monokai Extended 256 prefixes (fallback)
    m={
     'default':'\x1b[38;5;231m','keyword':'\x1b[38;5;203m','storage':'\x1b[38;5;81m','operator':'\x1b[38;5;203m',
     'number':'\x1b[38;5;141m','string':'\x1b[38;5;186m','string_delim':'\x1b[38;5;186m','comment':'\x1b[38;5;242m','comment_delim':'\x1b[38;5;242m',
     'entity_function':'\x1b[38;5;149m','entity_type':'\x1b[4;38;5;81m','support_function':'\x1b[38;5;81m','support_type':'\x1b[38;5;149m','variable_parameter':'\x1b[38;5;208m','property':'\x1b[38;5;231m','json_key':'\x1b[38;5;208m','tag':'\x1b[38;5;203m','attribute':'\x1b[38;5;149m','heading':'\x1b[38;5;208m','string_interp':'\x1b[38;5;141m',
     'np_space':'\x1b[38;5;81m','np_tab':'\x1b[38;5;141m','np_newline':'\x1b[38;5;203m','np_carriage':'\x1b[38;5;186m','np_control':'\x1b[38;5;149m','np_unicode':'\x1b[38;5;242m','grid':'\x1b[38;5;246m',
    }
    return m

class Theme:
    def __init__(self,name,truecolor=False,italic=False):
        self.name=name; self.truecolor=truecolor; self.italic=italic
        self.data=THEME_DATA.get(name,{})
        self._def=_default_slots()
    def prefix(self,slot):
        # data format: slot -> {"256":..., "rgb":..., "256i":..., "rgbi":...}
        d=self.data.get(slot)
        if isinstance(d,dict):
            if self.truecolor:
                v=d.get('rgbi' if self.italic else 'rgb') or d.get('rgb') or d.get('256','')
            else:
                v=d.get('256i' if self.italic else '256') or d.get('256','')
            return v or ''
        if slot in self._def:
            v=self._def[slot]
            return v
        # fallback chain
        chain={'entity_type':'support_function','support_type':'entity_function','property':'default','attribute':'entity_function','tag':'keyword','heading':'number','json_key':'number','string_delim':'string','comment_delim':'comment','string_interp':'number','np_space':'support_function','np_tab':'number','np_newline':'keyword','np_carriage':'string','np_control':'entity_function','np_unicode':'comment','grid':'comment'}
        if slot in chain: return self.prefix(chain[slot])
        return self._def.get('default','')
    @property
    def grid_prefix(self):
        d=self.data.get('grid')
        if isinstance(d,dict):
            return (d.get('rgb') if self.truecolor else d.get('256')) or ''
        return self._def.get('grid','')
    @property
    def highlight_bg(self):
        """prefix fragment for background only, e.g. '\\x1b[48;5;236m' or for ansi special return None"""
        d=self.data.get('highlight_bg')
        if isinstance(d,dict):
            return (d.get('rgb') if self.truecolor else d.get('256'))
        if self.name=='ansi': return None
        return '\x1b[48;5;236m' if not self.truecolor else '\x1b[48;2;61;61;61m'

