def _family(syntax):
    s=syntax or 'Plain Text'
    if s in ('Plain Text',): return 'plain'
    if s=='Highlight non-printables': return 'nonprint'
    if s=='Python': return 'python'
    if s=='Rust': return 'rust'
    if s in ('JavaScript (Babel)','JavaScript','TypeScript','TypeScriptReact','JavaScript (Rails)'): return 'js'
    if s in ('C','C++','C#','Java','Go','Kotlin','Scala','Swift','D','Dart','Objective-C','Objective-C++','Groovy','PHP'): return 'clike'
    if s=='Go': return 'clike'
    if s in ('Bourne Again Shell (bash)','Fish'): return 'shell'
    if s=='Ruby': return 'ruby'
    if s=='JSON' or s=='jsonnet': return 'json'
    if s in ('HTML','HTML (Rails)','HTML (Jinja2)','XML','HTML (ASP)','HTML (Twig)','HTML (EEx)','HTML (Erlang)','HTML (Tcl)'): return 'html'
    if s in ('CSS','SCSS','Sass','Less','Stylus'): return 'css'
    if s=='Markdown': return 'markdown'
    if s=='Diff': return 'diff'
    if s in ('Command Help',): return 'help'
    if s in ('Manpage','Groff/troff'): return 'man'
    if s in ('YAML','TOML','INI','Git Config','Dockerfile','Makefile','CMake','nginx','Apache Conf','Git Ignore','Git Attributes'): return 'config'
    if s=='SQL' or s.startswith('SQL'): return 'sql'
    if s=='Lua': return 'lua'
    if s in ('Haskell','Literate Haskell'): return 'haskell'
    if s in ('Lisp','Clojure','Racket'): return 'lisp'
    # many hash-comment languages
    if s in ('Perl','R','Julia','Elixir','Crystal','PowerShell','AWK','CoffeeScript','Nim','Zig','Vyper'): return 'hashcode'
    return 'generic'

class Highlighter:
    def __init__(self,syntax,theme):
        self.syntax=syntax or 'Plain Text'
        self.theme=theme
        self.family=_family(self.syntax)
        self.state=None  # e.g. ('blockcomment',), ('string',quote), ('triple',quote)
        self.brace=0
    def _tok(self,slot,text):
        if text: return (slot,text)
    def highlight(self,text):
        if self.family=='plain':
            return [('default',text)] if text else []
        if self.family=='nonprint':
            return highlight_nonprint(text)
        if self.family=='diff':
            return highlight_diff(text,self)
        if self.family=='markdown':
            return highlight_markdown(text,self)
        if self.family=='help':
            return highlight_help(text,self)
        if self.family=='man':
            return highlight_man(text,self)
        if self.family=='html':
            return lex_html(text,self)
        return lex_code(text,self)

def highlight_nonprint(text):
    toks=[]; i=0; buf=''
    def flush():
        nonlocal buf
        if buf: toks.append(('default',buf)); buf=''
    while i<len(text):
        c=text[i]
        if c=='·':
            flush(); toks.append(('np_space','·')); i+=1; continue
        if c=='↹':
            flush(); toks.append(('np_tab','↹')); i+=1; continue
        if c=='├':
            j=i+1
            while j<len(text) and text[j]=='─': j+=1
            if j<len(text) and text[j]=='┤':
                flush(); toks.append(('np_tab',text[i:j+1])); i=j+1; continue
            buf+=c; i+=1; continue
        if c=='␊':
            flush(); toks.append(('np_newline','␊')); i+=1; continue
        if c=='␍':
            flush(); toks.append(('np_carriage','�'.replace('',''))); i+=1; continue
        if '␀'<=c<='␛':
            flush(); toks.append(('np_control',c)); i+=1; continue
        if text.startswith('\\u{',i):
            j=text.find('}',i)
            if j!=-1:
                flush(); toks.append(('np_unicode',text[i:j+1])); i=j+1; continue
        if re.match(r'\\x[0-9A-Fa-f]{2}(?![0-9A-Fa-f])',text[i:]):
            flush(); toks.append(('np_unicode',text[i:i+4])); i+=4; continue
        buf+=c; i+=1
    flush(); return toks

def highlight_diff(text,hl):
    if text.startswith('+++') or text.startswith('---'):
        return [('entity_function' if False else 'comment',text)] if False else _diff_line(text)
    return _diff_line(text)
def _diff_line(text):
    if text.startswith('+'): return [('string',text)]
    if text.startswith('-'): return [('keyword',text)]
    if text.startswith('@@'): return [('support_function',text)]
    if text.startswith('diff ') or text.startswith('index ') or text.startswith('Index:'): return [('comment',text)]
    return [('default',text)]

def highlight_help(text,hl):
    return lex_help_line(text)
def lex_help_line(text):
    # returns slots; approximate Sublime "Command Help" syntax
    toks=[]
    def add(slot,s):
        if s: toks.append((slot,s))
    # headings like "Usage:" "Arguments:" "Options:"
    m=re.match(r'^([A-Z][A-Za-z ]*:)',text)
    if m and m.group(1).strip() in ('Usage:','Arguments:','Options:','Commands:','Arguments','Options') or (m and text.rstrip().endswith(':') and len(text.strip())<30 and m.group(1)[:-1].isalpha()):
        add('heading',m.group(1)); rest=text[m.end():]
        if rest:
            # continue generic handling below on rest
            return toks+_help_rest(rest)
        return toks
    return _help_rest(text)
def _help_rest(text):
    toks=[]; i=0
    # tokenize preserving whitespace as separate default tokens, flags as entity_function-ish etc
    while i<len(text):
        m=re.match(r'\s+',text[i:])
        if m: toks.append(('default',m.group(0))); i+=m.end(); continue
        m=re.match(r'(--[a-zA-Z0-9][a-zA-Z0-9-]*|-[a-zA-Z])',text[i:])
        if m: toks.append(('entity_function',m.group(0))); i+=m.end(); continue
        m=re.match(r'(<[^>\s]+>|\[[A-Z][A-Z0-9_-]*\]|\[FILE\]\.\.\.)',text[i:])
        if m: toks.append(('keyword',m.group(0))); i+=m.end(); continue
        m=re.match(r'\bbat\b',text[i:])
        if m: toks.append(('number',m.group(0))); i+=m.end(); continue
        # a word / run until whitespace or flag-like
        m=re.match(r'[^\s]+',text[i:])
        if m: toks.append(('default',m.group(0))); i+=m.end(); continue
        toks.append(('default',text[i])); i+=1
    return toks

def highlight_man(text,hl):
    # Simplified: headings in caps, flags
    if re.match(r'^[A-Z][A-Z ]+$',text.strip()) and text.strip():
        return [('heading',text)]
    return lex_help_line(text)

def highlight_markdown(text,hl):
    toks=[]
    if re.match(r'^#+\s',text) or re.match(r'^[A-Z].*\n?$',text) and False:
        m=re.match(r'^(#+)(\s*)(.*)$',text)
        if m:
            toks.append(('heading',m.group(1))); 
            if m.group(2): toks.append(('heading',m.group(2)))
            if m.group(3): toks.append(('heading',m.group(3)))
            return toks
    # inline bold/italic/code/links simplified
    i=0; buf=''
    def flush():
        nonlocal buf
        if buf: toks.append(('default',buf)); buf=''
    while i<len(text):
        if text.startswith('**',i):
            j=text.find('**',i+2)
            if j!=-1:
                flush(); toks.append(('bold','**')); 
                if j>i+2: toks.append(('bold',text[i+2:j]))
                toks.append(('bold','**')); i=j+2; continue
        if text[i]=='`':
            j=text.find('`',i+1)
            if j!=-1:
                flush(); toks.append(('string',text[i:j+1])); i=j+1; continue
        buf+=text[i]; i+=1
    flush(); return toks

def lex_html(text,hl):
    toks=[]; i=0
    while i<len(text):
        if text.startswith('<!--',i):
            j=text.find('-->',i)
            end=len(text) if j==-1 else j+3
            toks.append(('comment',text[i:end])); i=end; continue
        if text[i]=='<':
            m=re.match(r'</?([A-Za-z][A-Za-z0-9-]*)?',text[i:])
            if m:
                # < or </ as default, tag name keyword
                full=m.group(0)
                # split
                lt=re.match(r'</?',full).group(0)
                toks.append(('default',lt)); idx=len(lt)
                if m.group(1): toks.append(('tag',m.group(1)))
                i+=len(full)
                # attributes until >
                while i<len(text) and text[i]!='>':
                    m2=re.match(r'\s+',text[i:])
                    if m2: toks.append(('default',m2.group(0))); i+=m2.end(); continue
                    m2=re.match(r'([A-Za-z_:][-A-Za-z0-9_:.]*)',text[i:])
                    if m2: toks.append(('attribute',m2.group(0))); i+=m2.end(); continue
                    if text[i] in '"\'':
                        q=text[i]; j=i+1
                        toks.append(('string_delim',q))
                        while j<len(text) and text[j]!=q: j+=1
                        if j>i+1: toks.append(('string',text[i+1:j]))
                        if j<len(text): toks.append(('string_delim',q)); j+=1
                        i=j; continue
                    toks.append(('default',text[i])); i+=1
                if i<len(text): toks.append(('default','>')); i+=1
                continue
            toks.append(('default','<')); i+=1; continue
        # text run until <
        j=text.find('<',i)
        if j==-1: j=len(text)
        if j>i: toks.append(('default',text[i:j])); i=j
        else: i+=1
    return toks

# Generic code lexer
def _kw_sets(fam,syntax):
    if fam=='python': return KEYWORDS['Python'][0]
    if fam=='rust': return RUST_KEYWORD|RUST_STORAGE
    if fam=='js': return JS_KEYWORD
    if syntax=='Go': return GO_KEYWORD
    if syntax in ('Java','Kotlin','Scala'): return JAVA_KEYWORD
    if syntax=='PHP': return PHP_KEYWORD
    if syntax in ('C',): return C_KEYWORD
    if syntax in ('C++','C#'): return C_KEYWORD|CPP_EXTRA
    if fam=='shell': return SHELL_KEYWORD
    if fam=='ruby': return RUBY_KEYWORD
    if fam=='sql': return {k.upper() for k in SQL_KEYWORD}
    if fam=='lua': return LUA_KEYWORD
    return GENERIC_KEYWORD

def lex_code(text,hl):
    fam=hl.family; syntax=hl.syntax
    toks=[]; i=0; n=len(text)
    kw=_kw_sets(fam,syntax)
    prev_significant=''  # previous non-space token text
    # state continuation
    if hl.state:
        st=hl.state
        if st[0]=='blockcomment':
            j=text.find('*/')
            if j==-1:
                if text: toks.append(('comment',text))
                return toks
            else:
                if j>0: toks.append(('comment',text[:j]))
                toks.append(('comment_delim','*/'))
                hl.state=None; i=j+2
        elif st[0] in ('string','triple'):
            q=st[1]
            # find closing
            j=_find_string_end(text,0,q,fam)
            if j is None:
                if text: toks.append(('string',text))
                return toks
            else:
                if j>0: toks.append(('string',text[:j]))
                toks.append(('string_delim',q)); hl.state=None; i=j+len(q)
    def add(slot,s):
        nonlocal prev_significant
        if not s: return
        toks.append((slot,s))
        if s.strip(): prev_significant=s
    while i<n:
        c=text[i]
        # whitespace
        m=re.match(r'[ \t]+',text[i:])
        if m:
            add('default',m.group(0)); i+=m.end(); continue
        # comments
        if fam in ('clike','js','rust','css','generic','hashcode') or syntax in ('PHP',):
            if text.startswith('//',i):
                add('comment_delim','//')
                if i+2<n: add('comment',text[i+2:])
                break
            if text.startswith('/*',i):
                j=text.find('*/',i+2)
                add('comment_delim','/*')
                if j==-1:
                    if i+2<n: add('comment',text[i+2:])
                    hl.state=('blockcomment',); break
                else:
                    if j>i+2: add('comment',text[i+2:j])
                    add('comment_delim','*/'); i=j+2; continue
        if fam in ('python','shell','ruby','hashcode','config') or syntax in ('Perl','PowerShell'):
            if c=='#':
                # in shell, # only comment at word start -- our position is token start (after space or line start or operator) approx
                add('comment_delim','#')
                if i+1<n: add(_comment_body_slot(fam),text[i+1:])
                break
        if fam=='sql' and text.startswith('--',i):
            add('comment_delim','--'); 
            if i+2<n: add('comment',text[i+2:])
            break
        if fam=='lisp' and c==';':
            add('comment_delim',';'); 
            if i+1<n: add('comment',text[i+1:])
            break
        if fam=='haskell' and text.startswith('--',i):
            add('comment_delim','--')
            if i+2<n: add('comment',text[i+2:])
            break
        # strings
        if c in ('"',"'",'`'):
            # python triple
            if fam=='python' and (text.startswith("'''",i) or text.startswith('"""',i)):
                q=text[i:i+3]; add('string_delim',q); j=text.find(q,i+3)
                if j==-1:
                    if i+3<n: add('string',text[i+3:])
                    hl.state=('triple',q); break
                if j>i+3: _add_string_body(add,text[i+3:j],fam)
                add('string_delim',q); i=j+3; continue
            # shell single quote no escape
            q=c; add('string_delim',q)
            j=1; start=i+1; found=None
            while start+j-1 < n:
                # find unescaped matching
                idx=_find_string_end(text,i,q,fam)
                found=idx; break
            if found is None:
                if i+1<n: _add_string_body(add,text[i+1:],fam)
                # JS template strings multiline, others not really; python non-triple unterminated ends at EOL
                if q=='`' and fam=='js': hl.state=('string',q)
                break
            if found>i+1: _add_string_body(add,text[i+1:found],fam)
            add('string_delim',q); i=found+1; continue
        # Python string prefixes r/b/f/ur etc followed by quote: handled as identifier below would misclass; check ahead
        if fam=='python':
            m=re.match(r"(?i)(r|b|f|rb|br|rf|fr|u)('''|\"\"\"|'|\")",text[i:])
            if m:
                # treat whole inc prefix as part of string delim? Sublime tokenises prefix with string delim maybe
                qlen=len(m.group(2)); add('string_delim',text[i:i+len(m.group(1))+qlen])
                # reuse simple by stepping back: easier: emulate
                # We'll instead handle by treating prefix+quote as delim and scanning body
                q=m.group(2); body_start=i+len(m.group(1))+len(q)
                if len(q)==3:
                    j=text.find(q,body_start)
                    if j==-1:
                        if body_start<n: _add_string_body(add,text[body_start:],fam)
                        hl.state=('triple',q); break
                    if j>body_start: _add_string_body(add,text[body_start:j],fam)
                    add('string_delim',q); i=j+3; continue
                idx=_find_string_end_at(text,body_start-1,q) if False else None
                # find end starting body_start with escape rules
                j=body_start; end=None
                while j<n:
                    if text[j]=='\\': j+=2; continue
                    if text.startswith(q,j): end=j; break
                    j+=1
                if end is None:
                    if body_start<n: _add_string_body(add,text[body_start:],fam)
                    break
                if end>body_start: _add_string_body(add,text[body_start:end],fam)
                add('string_delim',q); i=end+len(q); continue
        # numbers
        m=re.match(r'(0[xX][0-9A-Fa-f_]+|0[bB][01_]+|0[oO][0-7_]+|\d[\d_]*(?:\.\d[\d_]*)?(?:[eE][+-]?\d+)?|\.\d+(?:[eE][+-]?\d+)?)',text[i:])
        if m and (c.isdigit() or c=='.'):
            add('number',m.group(0)); i+=m.end(); continue
        # identifiers / keywords
        m=re.match(r'[A-Za-z_$][A-Za-z0-9_$]*',text[i:])
        if m:
            word=m.group(0); i2=i+m.end()
            slot=_classify_word(word,fam,syntax,kw,prev_significant,text,i2)
            add(slot,word); i=i2; continue
        # variable $foo in shell/php/ruby etc
        m=re.match(r'\$[A-Za-z_][A-Za-z0-9_]*',text[i:])
        if m and fam in ('shell','clike','ruby'):
            add('variable_parameter' if fam=='shell' else 'default',m.group(0)); i+=m.end(); continue
        # operators: syntect groups some multi-char operators
        m=re.match(r'(==|!=|<=|>=|->|=>|&&|\|\||\+\+|--|::|\.\.\.|\.\.|<<|>>|\+=|-=|\*=|/=|%=|\*\*|//|:=)',text[i:])
        if m and (fam not in ('shell',) or m.group(0) not in ('//',)):
            add('operator',m.group(0)); i+=m.end(); continue
        if c in '=+-%*/<>!&|^~?:':
            # colon is often default punctuation in python (class Foo:) - operator slot only for some? In Py sample '=' operator, ':' after Foo was default
            if c==':' and fam in ('python','rust','js'):
                add('default',c)
            else:
                add('operator',c)
            i+=1; continue
        # punctuation single char default
        add('default',c); i+=1; continue
    return toks

def _comment_body_slot(fam):
    return 'comment'
def _add_string_body(add,body,fam):
    # Rust format placeholders {} and {name:.2} colored number inside strings in println? Only in format strings; sublime Rust highlights interpolation in all strings
    if fam=='rust':
        # split { ... } with no nesting / {{ }}
        i=0
        import re as _re
        while i<len(body):
            m=_re.search(r'\{[^{}]*\}',body[i:])
            if not m:
                add('string',body[i:]); return
            s=i+m.start(); e=i+m.end()
            if s>i: add('string',body[i:s])
            add('string_interp',body[s:e]); i=e
        return
    add('string',body)

def _find_string_end(text,quote_pos,q,fam):
    # quote_pos index of opening quote char (single char q)
    i=quote_pos+1
    while i<len(text):
        if text[i]=='\\':
            if fam=='shell' and q=="'":
                pass
            else:
                i+=2; continue
        if text[i]==q:
            return i
        i+=1
    return None
def _find_string_end_at(text,pos,q): return None

def _classify_word(word,fam,syntax,kw,prev,next_text_start_idx):
    # next char info via prev? we don't have full text here in helper signature misuse: next_text_start_idx is index, not text
    return classify_word(word,fam,syntax,kw,prev)

def classify_word(word,fam,syntax,kw,prev,next_char=''):
    # prev significant token string
    if fam=='python':
        if word in kw: return 'keyword'
        if word in ('True','False','None'): return 'number'
        if prev=='class': return 'entity_type'
        if prev=='def': return 'entity_function'
        if prev in ('(', ','):
            # parameters in def signature are hard to know; approximation in lexer: all identifiers after '(' in function def line will be handled?... default for now
            pass
        if word in PY_BUILTINS: return 'support_function'
        return 'default'
    if fam=='rust':
        if word in RUST_STORAGE:
            if word=='pub': return 'keyword'
            return 'storage'
        if word in RUST_KEYWORD: return 'keyword'
        if word in ('true','false'): return 'number'
        if word in ('Self','i32','i64','u32','u64','usize','isize','f32','f64','bool','char','str','String','Vec','Option','Result','Some','None','Ok','Err'):
            return 'storage' if word in ('Self','i32','i64','u32','u64','usize','isize','f32','f64','bool','char','str') else 'default'
        if prev in ('fn','struct','enum','trait','impl','type'): return 'entity_function' if prev=='fn' else 'entity_function'
        return 'default'
    if fam=='js':
        if word in ('const','let','var','function','class'): return 'storage'
        if word in kw: return 'keyword'
        if word in ('true','false','null','undefined'): return 'number'
        if word in ('console','window','document','Math','JSON','Promise','Object','Array','String','Number','Boolean'): return 'support_type'
        if prev=='.': return 'support_function'
        if prev=='function': return 'entity_function'
        return 'default'
    if fam=='shell':
        if word in kw: return 'keyword'
        if word in SHELL_BUILTIN: return 'support_function'
        return 'default'
    if fam=='sql':
        if word.upper() in kw: return 'keyword'
        return 'default'
    if fam=='json':
        if word in ('true','false','null'): return 'number'
        return 'default'
    if word in kw: return 'keyword'
    if word in ('true','false','null','nil','None'): return 'number'
    return 'default'

