def get_xdg_config_home():
    v=os.environ.get('XDG_CONFIG_HOME')
    if v and os.path.isabs(v):
        return v
    return None

def languages_for_listing():
    """Return list of (name, extensions) with dynamic home/xdg paths substituted."""
    home_cfg=os.path.join(get_home(),'.config')
    xdg=get_xdg_config_home()
    out=[]
    for name,exts in LANGUAGES:
        new=[e.replace('__HOME_CONFIG__',home_cfg) for e in exts]
        if xdg and xdg!=home_cfg:
            if name=='Git Attributes':
