def find_syntax_by_token(token):
    if token is None: return None
    t=token.lower()
    # name match first (case-insensitive)
    for name,exts in LANGUAGES:
        if name.lower()==t:
            return name
    for name,exts in languages_for_listing():
        for e in exts:
            if e.lower()==t:
                return name
    return None

def _glob_match(pat, path, basename):
    # fnmatch with ** : Python fnmatch translates ** as * (matches slash too for fnmatchcase? fnmatch uses os.path.normcase and * matches / as well in fnmatch module)
    # try full path and basename
    # patterns like /etc/... match path; **/x matches path suffix
    candidates=[path, basename]
    # also path without leading /
    for c in candidates:
        if fnmatch.fnmatchcase(c, pat):
            return True
    # handle **/ prefix
    if pat.startswith('**/'):
        if fnmatch.fnmatchcase(basename, pat[3:]) or fnmatch.fnmatchcase(path, pat[3:]):
            return True
    return False

def detect_syntax(path_for_detection, first_line_text, explicit=None, fallback=None, map_syntax=None, ignored_suffixes=None, show_all=False):
    """Return (syntax_name or None-if-unknown-explicit-req, unknown_token)
    If explicit given and unknown: return (None, explicit)
    map_syntax: list of (pattern, rhs)
    path_for_detection: string path or None for stdin without name
    """
    if show_all:
        return ('Highlight non-printables', None)
    if explicit is not None:
        s=find_syntax_by_token(explicit)
        return (s, None if s else explicit)
    path=path_for_detection
    if path:
        # ignored suffix stripping: while current extension (after last dot in basename) matches a suffix '.ext'
        if ignored_suffixes:
            p=path
            while True:
                base=os.path.basename(p)
                if '.' not in base: break
                ext='.'+base.rsplit('.',1)[1]
                if ext in ignored_suffixes:
                    p=p[:len(p)-len(ext)]
                else:
                    break
            path=p
        base=os.path.basename(path)
        # user map syntax: test in order; what wins on multiple? Use first matching? We will refine after probing (later overrides likely)
        if map_syntax:
            for pat,rhs in map_syntax:
                if _glob_match(pat, path, base):
                    s=find_syntax_by_token(rhs)
                    return (s, None if s else rhs)
        langs=languages_for_listing()
        # 1) glob-pattern entries (contain *, ?, [, or / with wildcard patterns?) - match
        best=None; bestscore=-1
        for name,exts in langs:
            for e in exts:
                if any(ch in e for ch in '*?['):
                    if _glob_match(e, path, base):
                        score=len(e)
                        if score>bestscore: best=name; bestscore=score
                elif '/' in e:
                    # absolute / path specific entries without wildcards: match full path exactly
                    if path==e:
                        return (name,None)
        if best:
            return (best,None)
        # 2) filename / extension entries by specificity (longest entry matched)
        best=None; bestscore=-1; bestexact=False
        lower_base=base.lower()
        for name,exts in langs:
            for e in exts:
                if any(ch in e for ch in '*?['): continue
                el=e.lower()
                exact = (lower_base==el)
                suffix = lower_base.endswith('.'+el)
                if exact or suffix:
                    score=len(e)+(1000 if exact else 0)
                    if score>bestscore:
                        best=name; bestscore=score; bestexact=exact
        if best:
            return (best,None)
    # 3) first line
    if first_line_text:
        s=detect_first_line(first_line_text)
        if s:
            return (s,None)
    if fallback is not None:
        s=find_syntax_by_token(fallback)
        return (s, None if s else fallback)
    return ('Plain Text', None)

_INTERPRETERS={
 'python':'Python','python3':'Python','pypy':'Python',
 'bash':'Bourne Again Shell (bash)','sh':'Bourne Again Shell (bash)','zsh':'Bourne Again Shell (bash)','ksh':'Bourne Again Shell (bash)','ash':'Bourne Again Shell (bash)','dash':'Bourne Again Shell (bash)',
 'fish':'Fish','node':'JavaScript (Babel)','nodejs':'JavaScript (Babel)','deno':'TypeScript','ruby':'Ruby','perl':'Perl','php':'PHP','lua':'Lua','Rscript':'R','julia':'Julia','groovy':'Groovy','osascript':'AppleScript','awk':'AWK','gawk':'AWK','mawk':'AWK','sed':'Bourne Again Shell (bash)','tclsh':'Tcl','wish':'Tcl','pwsh':'PowerShell','powershell':'PowerShell','elvish':'Bourne Again Shell (bash)','nu':'Bourne Again Shell (bash)','scala':'Scala','sbcl':'Lisp','clisp':'Lisp','racket':'Racket','guile':'Lisp','make':'Makefile',
}
def detect_first_line(line):
    l=line.rstrip('\r\n')
    if l.startswith('#!'):
        rest=l[2:].strip()
        # tokens
        parts=re.split(r'\s+',rest)
        if parts:
            first=parts[0]
            base=os.path.basename(first)
            if base=='env':
                # skip env options / assignments
                j=1
                while j<len(parts) and (parts[j].startswith('-') or '=' in parts[j]):
                    if parts[j]=='-S' and j+1<len(parts):
                        # next is command string maybe
                        pass
                    j+=1
                if j<len(parts):
                    base=os.path.basename(parts[j])
                else:
                    base=''
            # strip version suffix digits/dots
            cand=re.sub(r'[\d.]+$','',base)
            for key in (base,cand):
                if key in _INTERPRETERS: return _INTERPRETERS[key]
            s=find_syntax_by_token(base) or find_syntax_by_token(cand)
            if s: return s
        # fallback regex search python etc anywhere
        m=re.search(r'\b(python|bash|sh|zsh|fish|node|ruby|perl|php|lua)\b',rest)
        if m and m.group(1) in _INTERPRETERS: return _INTERPRETERS[m.group(1)]
        return None
    # emacs / vim modelines anywhere in first line
    m=re.search(r'-\*-.*?(?:mode\s*:\s*|mode\s*=\s*)([A-Za-z0-9_+-]+)',l,re.I)
    if m:
        s=find_syntax_by_token(m.group(1))
        if s: return s
    m=re.search(r'(?:^|\s)(?:vim|vi|ex)\s*:.*?(?:filetype|ft)\s*=\s*([A-Za-z0-9_+-]+)',l,re.I)
    if m:
        s=find_syntax_by_token(m.group(1))
        if s: return s
    if l.startswith('<?xml'):
        return 'XML'
    if l.startswith('<?php'):
        return 'PHP'
    if re.match(r'<!DOCTYPE\s+html',l,re.I) or re.match(r'<html[\s>]',l,re.I):
        return 'HTML'
    if l.startswith('diff --git ') or l.startswith('Index: ') or l.startswith('--- '):
        # --- could be yaml; only treat if looks diff with +++ later not known; syntect diff first line is ^diff or ^Index
        if not l.startswith('--- '): return 'Diff'
    if l.startswith('.TH ') or l.startswith('.\\"'):
        return 'Manpage'
    return None

