        for name,exts in langs:
            for e in exts:
                if any(ch in e for ch in '*?['): continue
                el=e.lower()
                exact = (lower_base==el)
                suffix = lower_base.endswith('.'+el)
                if exact or suffix:
                    score=len(e)+(1000 if exact else 0)
                    if score>bestscore:
                        best=name; bestscore=score; bestexact=exact
        if best:
            return (best,None)
    # 3) first line
    if first_line_text:
        s=detect_first_line(first_line_text)
        if s:
            return (s,None)
    if fallback is not None:
        s=find_syntax_by_token(fallback)
        return (s, None if s else fallback)
    return ('Plain Text', None)

_INTERPRETERS={
 'python':'Python','python3':'Python','pypy':'Python',
 'bash':'Bourne Again Shell (bash)','sh':'Bourne Again Shell (bash)','zsh':'Bourne Again Shell (bash)','ksh':'Bourne Again Shell (bash)','ash':'Bourne Again Shell (bash)','dash':'Bourne Again Shell (bash)',
 'fish':'Fish','node':'JavaScript (Babel)','nodejs':'JavaScript (Babel)','deno':'TypeScript','ruby':'Ruby','perl':'Perl','php':'PHP','lua':'Lua','Rscript':'R','julia':'Julia','groovy':'Groovy','osascript':'AppleScript','awk':'AWK','gawk':'AWK','mawk':'AWK','sed':'Bourne Again Shell (bash)','tclsh':'Tcl','wish':'Tcl','pwsh':'PowerShell','powershell':'PowerShell','elvish':'Bourne Again Shell (bash)','nu':'Bourne Again Shell (bash)','scala':'Scala','sbcl':'Lisp','clisp':'Lisp','racket':'Racket','guile':'Lisp','make':'Makefile',
}
def detect_first_line(line):
    l=line.rstrip('\r\n')
    if l.startswith('#!'):
        rest=l[2:].strip()
        # tokens
        parts=re.split(r'\s+',rest)
        if parts:
            first=parts[0]
            base=os.path.basename(first)
            if base=='env':
                # skip env options / assignments
                j=1
                while j<len(parts) and (parts[j].startswith('-') or '=' in parts[j]):
                    if parts[j]=='-S' and j+1<len(parts):
                        # next is command string maybe
                        pass
                    j+=1
                if j<len(parts):
                    base=os.path.basename(parts[j])
                else:
                    base=''
            # strip version suffix digits/dots
            cand=re.sub(r'[\d.]+$','',base)
            for key in (base,cand):
                if key in _INTERPRETERS: return _INTERPRETERS[key]
            s=find_syntax_by_token(base) or find_syntax_by_token(cand)
            if s: return s
        # fallback regex search python etc anywhere
        m=re.search(r'\b(python|bash|sh|zsh|fish|node|ruby|perl|php|lua)\b',rest)
        if m and m.group(1) in _INTERPRETERS: return _INTERPRETERS[m.group(1)]
        return None
    # emacs / vim modelines anywhere in first line
    m=re.search(r'-\*-.*?(?:mode\s*:\s*|mode\s*=\s*)([A-Za-z0-9_+-]+)',l,re.I)
    if m:
        s=find_syntax_by_token(m.group(1))
        if s: return s
    m=re.search(r'(?:^|\s)(?:vim|vi|ex)\s*:.*?(?:filetype|ft)\s*=\s*([A-Za-z0-9_+-]+)',l,re.I)
    if m:
        s=find_syntax_by_token(m.group(1))
        if s: return s
    if l.startswith('<?xml'):
        return 'XML'
    if l.startswith('<?php'):
        return 'PHP'
    if re.match(r'<!DOCTYPE\s+html',l,re.I) or re.match(r'<html[\s>]',l,re.I):
        return 'HTML'
    if l.startswith('diff --git ') or l.startswith('Index: ') or l.startswith('--- '):
        # --- could be yaml; only treat if looks diff with +++ later not known; syntect diff first line is ^diff or ^Index
        if not l.startswith('--- '): return 'Diff'
    if l.startswith('.TH ') or l.startswith('.\\"'):
        return 'Manpage'
    return None

