     'number':'\x1b[38;5;141m','string':'\x1b[38;5;186m','string_delim':'\x1b[38;5;186m','comment':'\x1b[38;5;242m','comment_delim':'\x1b[38;5;242m',
     'entity_function':'\x1b[38;5;149m','entity_type':'\x1b[4;38;5;81m','support_function':'\x1b[38;5;81m','support_type':'\x1b[38;5;149m','variable_parameter':'\x1b[38;5;208m','property':'\x1b[38;5;231m','json_key':'\x1b[38;5;208m','tag':'\x1b[38;5;203m','attribute':'\x1b[38;5;149m','heading':'\x1b[38;5;208m','string_interp':'\x1b[38;5;141m',
