def _family(syntax):
    s=syntax or 'Plain Text'
    if s in ('Plain Text',): return 'plain'
    if s=='Highlight non-printables': return 'nonprint'
    if s=='Python': return 'python'
    if s=='Rust': return 'rust'
    if s in ('JavaScript (Babel)','JavaScript','TypeScript','TypeScriptReact','JavaScript (Rails)'): return 'js'
    if s in ('C','C++','C#','Java','Go','Kotlin','Scala','Swift','D','Dart','Objective-C','Objective-C++','Groovy','PHP'): return 'clike'
    if s=='Go': return 'clike'
    if s in ('Bourne Again Shell (bash)','Fish'): return 'shell'
    if s=='Ruby': return 'ruby'
    if s=='JSON' or s=='jsonnet': return 'json'
    if s in ('HTML','HTML (Rails)','HTML (Jinja2)','XML','HTML (ASP)','HTML (Twig)','HTML (EEx)','HTML (Erlang)','HTML (Tcl)'): return 'html'
    if s in ('CSS','SCSS','Sass','Less','Stylus'): return 'css'
    if s=='Markdown': return 'markdown'
    if s=='Diff': return 'diff'
    if s in ('Command Help',): return 'help'
    if s in ('Manpage','Groff/troff'): return 'man'
    if s in ('YAML','TOML','INI','Git Config','Dockerfile','Makefile','CMake','nginx','Apache Conf','Git Ignore','Git Attributes'): return 'config'
    if s=='SQL' or s.startswith('SQL'): return 'sql'
    if s=='Lua': return 'lua'
    if s in ('Haskell','Literate Haskell'): return 'haskell'
    if s in ('Lisp','Clojure','Racket'): return 'lisp'
    # many hash-comment languages
    if s in ('Perl','R','Julia','Elixir','Crystal','PowerShell','AWK','CoffeeScript','Nim','Zig','Vyper'): return 'hashcode'
    return 'generic'

class Highlighter:
    def __init__(self,syntax,theme):
        self.syntax=syntax or 'Plain Text'
        self.theme=theme
        self.family=_family(self.syntax)
        self.state=None  # e.g. ('blockcomment',), ('string',quote), ('triple',quote)
        self.brace=0
    def _tok(self,slot,text):
        if text: return (slot,text)
    def highlight(self,text):
        if self.family=='plain':
            return [('default',text)] if text else []
        if self.family=='nonprint':
            return highlight_nonprint(text)
        if self.family=='diff':
            return highlight_diff(text,self)
        if self.family=='markdown':
            return highlight_markdown(text,self)
        if self.family=='help':
            return highlight_help(text,self)
        if self.family=='man':
            return highlight_man(text,self)
        if self.family=='html':
            return lex_html(text,self)
        return lex_code(text,self)

def highlight_nonprint(text):
    toks=[]; i=0; buf=''
    def flush():
        nonlocal buf
        if buf: toks.append(('default',buf)); buf=''
    while i<len(text):
        c=text[i]
        if c=='·':
            flush(); toks.append(('np_space','·')); i+=1; continue
        if c=='↹':
            flush(); toks.append(('np_tab','↹')); i+=1; continue
        if c=='├':
            j=i+1
            while j<len(text) and text[j]=='─': j+=1
            if j<len(text) and text[j]=='┤':
                flush(); toks.append(('np_tab',text[i:j+1])); i=j+1; continue
            buf+=c; i+=1; continue
        if c=='␊':
            flush(); toks.append(('np_newline','␊')); i+=1; continue
        if c=='␍':
            flush(); toks.append(('np_carriage','�'.replace('',''))); i+=1; continue
        if '␀'<=c<='␛':
            flush(); toks.append(('np_control',c)); i+=1; continue
        if text.startswith('\\u{',i):
            j=text.find('}',i)
            if j!=-1:
                flush(); toks.append(('np_unicode',text[i:j+1])); i=j+1; continue
        if re.match(r'\\x[0-9A-Fa-f]{2}(?![0-9A-Fa-f])',text[i:]):
            flush(); toks.append(('np_unicode',text[i:i+4])); i+=4; continue
        buf+=c; i+=1
    flush(); return toks

def highlight_diff(text,hl):
    if text.startswith('+++') or text.startswith('---'):
        return [('entity_function' if False else 'comment',text)] if False else _diff_line(text)
    return _diff_line(text)
def _diff_line(text):
    if text.startswith('+'): return [('string',text)]
    if text.startswith('-'): return [('keyword',text)]
    if text.startswith('@@'): return [('support_function',text)]
    if text.startswith('diff ') or text.startswith('index ') or text.startswith('Index:'): return [('comment',text)]
    return [('default',text)]

def highlight_help(text,hl):
    return lex_help_line(text)
def lex_help_line(text):
    # returns slots; approximate Sublime "Command Help" syntax
    toks=[]
    def add(slot,s):
        if s: toks.append((slot,s))
    # headings like "Usage:" "Arguments:" "Options:"
    m=re.match(r'^([A-Z][A-Za-z ]*:)',text)
    if m and m.group(1).strip() in ('Usage:','Arguments:','Options:','Commands:','Arguments','Options') or (m and text.rstrip().endswith(':') and len(text.strip())<30 and m.group(1)[:-1].isalpha()):
        add('heading',m.group(1)); rest=text[m.end():]
        if rest:
            # continue generic handling below on rest
            return toks+_help_rest(rest)
        return toks
    return _help_rest(text)
def _help_rest(text):
    toks=[]; i=0
    # tokenize preserving whitespace as separate default tokens, flags as entity_function-ish etc
    while i<len(text):
        m=re.match(r'\s+',text[i:])
        if m: toks.append(('default',m.group(0))); i+=m.end(); continue
        m=re.match(r'(--[a-zA-Z0-9][a-zA-Z0-9-]*|-[a-zA-Z])',text[i:])
        if m: toks.append(('entity_function',m.group(0))); i+=m.end(); continue
        m=re.match(r'(<[^>\s]+>|\[[A-Z][A-Z0-9_-]*\]|\[FILE\]\.\.\.)',text[i:])
        if m: toks.append(('keyword',m.group(0))); i+=m.end(); continue
        m=re.match(r'\bbat\b',text[i:])
        if m: toks.append(('number',m.group(0))); i+=m.end(); continue
        # a word / run until whitespace or flag-like
        m=re.match(r'[^\s]+',text[i:])
        if m: toks.append(('default',m.group(0))); i+=m.end(); continue
        toks.append(('default',text[i])); i+=1
    return toks

def highlight_man(text,hl):
    # Simplified: headings in caps, flags
    if re.match(r'^[A-Z][A-Z ]+$',text.strip()) and text.strip():
        return [('heading',text)]
    return lex_help_line(text)

def highlight_markdown(text,hl):
    toks=[]
    if re.match(r'^#+\s',text) or re.match(r'^[A-Z].*\n?$',text) and False:
        m=re.match(r'^(#+)(\s*)(.*)$',text)
        if m:
            toks.append(('heading',m.group(1))); 
            if m.group(2): toks.append(('heading',m.group(2)))
            if m.group(3): toks.append(('heading',m.group(3)))
            return toks
    # inline bold/italic/code/links simplified
    i=0; buf=''
    def flush():
        nonlocal buf
        if buf: toks.append(('default',buf)); buf=''
    while i<len(text):
        if text.startswith('**',i):
            j=text.find('**',i+2)
            if j!=-1:
                flush(); toks.append(('bold','**')); 
                if j>i+2: toks.append(('bold',text[i+2:j]))
                toks.append(('bold','**')); i=j+2; continue
        if text[i]=='`':
            j=text.find('`',i+1)
            if j!=-1:
                flush(); toks.append(('string',text[i:j+1])); i=j+1; continue
        buf+=text[i]; i+=1
    flush(); return toks

def lex_html(text,hl):
    toks=[]; i=0
    while i<len(text):
        if text.startswith('<!--',i):
            j=text.find('-->',i)
            end=len(text) if j==-1 else j+3
            toks.append(('comment',text[i:end])); i=end; continue
        if text[i]=='<':
            m=re.match(r'</?([A-Za-z][A-Za-z0-9-]*)?',text[i:])
            if m:
                # < or </ as default, tag name keyword
                full=m.group(0)
                # split
                lt=re.match(r'</?',full).group(0)
                toks.append(('default',lt)); idx=len(lt)
                if m.group(1): toks.append(('tag',m.group(1)))
                i+=len(full)
                # attributes until >
                while i<len(text) and text[i]!='>':
                    m2=re.match(r'\s+',text[i:])
                    if m2: toks.append(('default',m2.group(0))); i+=m2.end(); continue
                    m2=re.match(r'([A-Za-z_:][-A-Za-z0-9_:.]*)',text[i:])
                    if m2: toks.append(('attribute',m2.group(0))); i+=m2.end(); continue
                    if text[i] in '"\'':
                        q=text[i]; j=i+1
                        toks.append(('string_delim',q))
                        while j<len(text) and text[j]!=q: j+=1
                        if j>i+1: toks.append(('string',text[i+1:j]))
                        if j<len(text): toks.append(('string_delim',q)); j+=1
                        i=j; continue
                    toks.append(('default',text[i])); i+=1
                if i<len(text): toks.append(('default','>')); i+=1
                continue
            toks.append(('default','<')); i+=1; continue
        # text run until <
        j=text.find('<',i)
        if j==-1: j=len(text)
        if j>i: toks.append(('default',text[i:j])); i=j
        else: i+=1
    return toks

# Generic code lexer
def _kw_sets(fam,syntax):
    if fam=='python': return KEYWORDS['Python'][0]
    if fam=='rust': return RUST_KEYWORD|RUST_STORAGE
    if fam=='js': return JS_KEYWORD
    if syntax=='Go': return GO_KEYWORD
    if syntax in ('Java','Kotlin','Scala'): return JAVA_KEYWORD
    if syntax=='PHP': return PHP_KEYWORD
    if syntax in ('C',): return C_KEYWORD
    if syntax in ('C++','C#'): return C_KEYWORD|CPP_EXTRA
    if fam=='shell': return SHELL_KEYWORD
    if fam=='ruby': return RUBY_KEYWORD
    if fam=='sql': return {k.upper() for k in SQL_KEYWORD}
    if fam=='lua': return LUA_KEYWORD
    return GENERIC_KEYWORD

def lex_code(text,hl):
    fam=hl.family; syntax=hl.syntax
    toks=[]; i=0; n=len(text)
    kw=_kw_sets(fam,syntax)
    prev_significant=''  # previous non-space token text
    # state continuation
    if hl.state:
        st=hl.state
        if st[0]=='blockcomment':
            j=text.find('*/')
            if j==-1:
                if text: toks.append(('comment',text))
                return toks
            else:
                if j>0: toks.append(('comment',text[:j]))
                toks.append(('comment_delim','*/'))
                hl.state=None; i=j+2
        elif st[0] in ('string','triple'):
            q=st[1]
            # find closing
            j=_find_string_end(text,0,q,fam)
            if j is None:
                if text: toks.append(('string',text))
                return toks
            else:
                if j>0: toks.append(('string',text[:j]))
                toks.append(('string_delim',q)); hl.state=None; i=j+len(q)
    def add(slot,s):
        nonlocal prev_significant
        if not s: return
        toks.append((slot,s))
        if s.strip(): prev_significant=s
    while i<n:
        c=text[i]
        # whitespace
        m=re.match(r'[ \t]+',text[i:])
        if m:
            add('default',m.group(0)); i+=m.end(); continue
        # comments
        if fam in ('clike','js','rust','css','generic','hashcode') or syntax in ('PHP',):
            if text.startswith('//',i):
                add('comment_delim','//')
                if i+2<n: add('comment',text[i+2:])
                break
            if text.startswith('/*',i):
                j=text.find('*/',i+2)
                add('comment_delim','/*')
                if j==-1:
                    if i+2<n: add('comment',text[i+2:])
                    hl.state=('blockcomment',); break
                else:
                    if j>i+2: add('comment',text[i+2:j])
                    add('comment_delim','*/'); i=j+2; continue
        if fam in ('python','shell','ruby','hashcode','config') or syntax in ('Perl','PowerShell'):
            if c=='#':
                # in shell, # only comment at word start -- our position is token start (after space or line start or operator) approx
                add('comment_delim','#')
                if i+1<n: add(_comment_body_slot(fam),text[i+1:])
                break
        if fam=='sql' and text.startswith('--',i):
            add('comment_delim','--'); 
            if i+2<n: add('comment',text[i+2:])
            break
        if fam=='lisp' and c==';':
