            pass
        if word in PY_BUILTINS: return 'support_function'
        return 'default'
    if fam=='rust':
        if word in RUST_STORAGE:
            if word=='pub': return 'keyword'
            return 'storage'
        if word in RUST_KEYWORD: return 'keyword'
        if word in ('true','false'): return 'number'
        if word in ('Self','i32','i64','u32','u64','usize','isize','f32','f64','bool','char','str','String','Vec','Option','Result','Some','None','Ok','Err'):
            return 'storage' if word in ('Self','i32','i64','u32','u64','usize','isize','f32','f64','bool','char','str') else 'default'
        if prev in ('fn','struct','enum','trait','impl','type'): return 'entity_function' if prev=='fn' else 'entity_function'
        return 'default'
    if fam=='js':
        if word in ('const','let','var','function','class'): return 'storage'
        if word in kw: return 'keyword'
        if word in ('true','false','null','undefined'): return 'number'
        if word in ('console','window','document','Math','JSON','Promise','Object','Array','String','Number','Boolean'): return 'support_type'
        if prev=='.': return 'support_function'
        if prev=='function': return 'entity_function'
        return 'default'
