        try: up0=_rust_parse_usize(B)
        except RangeError: raise RangeError('Invalid end line number in N:M:C format')
        try: ctx=_rust_parse_usize(C)
        except RangeError: raise RangeError('Invalid context number in N:M:C format')
        lo=lo0-ctx if lo0>=ctx else 0; up=up0+ctx
