        sm=difflib.SequenceMatcher(None, oldl, newl, autojunk=False)
        changes={}
        for tag,i1,i2,j1,j2 in sm.get_opcodes():
            if tag=='equal': continue
            added=list(range(j1+1,j2+1))
            removed=i2-i1
            if added and removed:
                for a in added: changes[a]='~'
            elif added:
                for a in added: changes[a]='+'
            elif removed:
                # deletion after new line j1 (j1 lines already output); if j1==0 mark line1 above
                if j1==0:
                    if newl: changes[1]='\u203e'
                else:
                    changes[j1]='_'
