import re, unicodedata

def char_width(c):
    o=ord(c)
    if o==0: return 0
    if o<32 or (0x7f<=o<0xa0): return 0
    if unicodedata.combining(c): return 0
    cat=unicodedata.category(c)
    if cat in ('Mn','Me','Cf'):
        return 0
    if unicodedata.east_asian_width(c) in ('W','F'): return 2
    # many emoji are EAW Neutral in older unicode data but should be 2
    if o>=0x1F300 and o<=0x1FAFF: return 2
    if 0x2600<=o<=0x27BF: return 2
    return 1

def text_width(s):
    return sum(char_width(c) for c in s)

