def ansi_iter(text):
    """yield (is_escape, chunk)"""
    i=0
    while i<len(text):
        if text[i]=='\x1b':
            # CSI
            if i+1<len(text) and text[i+1]=='[':
                j=i+2
                while j<len(text) and not ('@'<=text[j]<='~'):
