                if j<len(text): j+=1
                yield (True,text[i:j]); i=j; continue
            if i+1<len(text) and text[i+1]==']':
                j=i+2
                while j<len(text):
                    if text[j]=='\x07': j+=1; break
                    if text[j]=='\x1b' and j+1<len(text) and text[j+1]=='\\': j+=2; break
                    j+=1
                yield (True,text[i:j]); i=j; continue
            # other ESC sequence: intermediates 0x20-0x2f then final 0x30-0x7e, or single char
            j=i+1
            if j<len(text) and (' '<=text[j]<='/'):
                while j<len(text) and (' '<=text[j]<='/'):
