        return text
    out=[]
    for esc,chunk in ansi_iter(text):
        if esc:
            out.append(chunk); continue
        for c in chunk:
            if c=='\t':
                n=tab_width - (cursor % tab_width)
                out.append(' '*n); cursor+=n
            else:
                out.append(c); cursor+=char_width(c)
