        self.hyperlink=None  # full OSC8 opening sequence string
        self.other=[]  # sequences like ESC(B to reapply in order
    def reset_sgr(self):
        self.fg=None; self.bg=None; self.attrs=set()
    def update(self,seq):
        if seq.startswith('\x1b[') and seq.endswith('m'):
            body=seq[2:-1]
            params=[]
            if body=='':
                params=[0]
            else:
                for p in body.split(';'):
                    try: params.append(int(p) if p!='' else 0)
                    except: params.append(0)
            i=0
            while i<len(params):
                p=params[i]
                if p==0: self.reset_sgr()
                elif p in (1,2,3,4,5,6,7,8,9): self.attrs.add(p)
                elif p==22: self.attrs.discard(1); self.attrs.discard(2)
                elif p==23: self.attrs.discard(3)
                elif p==24: self.attrs.discard(4)
                elif p==25: self.attrs.discard(5); self.attrs.discard(6)
                elif p==27: self.attrs.discard(7)
                elif p==28: self.attrs.discard(8)
                elif p==29: self.attrs.discard(9)
                elif 30<=p<=37 or 90<=p<=97: self.fg=[p]
                elif p==39: self.fg=None
                elif 40<=p<=47 or 100<=p<=107: self.bg=[p]
                elif p==49: self.bg=None
                elif p in (38,48):
