        for a in sorted(self.attrs):
            out.append(f'\x1b[{a}m')
        out.extend(self.other)
        if self.hyperlink: out.append(self.hyperlink)
        return ''.join(out)
    def has_any(self):
        return bool(self.fg or self.bg or self.attrs or self.other or self.hyperlink)

def combine_sgr(prefixes):
    """Combine ANSI prefix strings (each like \\x1b[...m or '') into one escape, preserving order of params.
