                if body: params.extend(body.split(';'))
                else: params.append('0')
            elif esc:
                others.append(chunk)
            elif chunk:
                others.append(chunk)
    out=''
    if params: out+='\x1b['+';'.join(params)+'m'
    out+=''.join(others)
    return out
