        if self.cfg.use_interactive and 'grid' in self.cfg.display_style and 'rule' in self.cfg.display_style:
            sys.stderr.write("\x1b[33m[bat warning]\x1b[0m: Style 'rule' is a subset of style 'grid', 'rule' will not be visible.\n")
    def run(self,inputs):
        self.warn_rule_once()
        first=True
        for spec in inputs:
            try:
                self.print_input(spec,first)
            except OpenError as e:
                sys.stderr.write(f"\x1b[31m[bat error]\x1b[0m: {e}\n")
                self.exit_error=True
            first=False
        self.w.flush()
        return 1 if self.exit_error else 0
    def open_reader(self,spec):
        size=None
        if spec.kind=='stdin':
            source=self._stdin_source
        else:
            path=spec.path
            try:
                st=os.stat(path)
            except OSError as e:
                raise OpenError(f"'{path}': {os.strerror(e.errno)} (os error {e.errno})")
            if stat.S_ISDIR(st.st_mode):
                raise OpenError(f"'{path}' is a directory.")
            size=st.st_size
            try:
                fp=open(path,'rb')
            except OSError as e:
                raise OpenError(f"'{path}': {os.strerror(e.errno)} (os error {e.errno})")
            source=FileSource(fp)
        reader=Reader(source,self.cfg.use_interactive,self.cfg.show_all)
        return reader,size,source
    def print_input(self,spec,first):
        cfg=self.cfg
        reader,size,source=self.open_reader(spec)
        # git diff (for files)
        git_status='no_repo'; line_changes={}
        need_git = (cfg.diff_mode or ('changes' in cfg.display_style))
        if spec.kind=='file' and need_git:
            git_status,line_changes=get_line_changes(spec.path)
        # visible ranges
        visible=cfg.line_ranges
        diff_skip=False
        if cfg.diff_mode:
            if spec.kind=='stdin':
                diff_skip=True; visible=LineRanges([])
            elif git_status=='empty':
                diff_skip=True; visible=LineRanges([])
            elif git_status=='changes':
                visible=ranges_from_changed(line_changes.keys(),cfg.diff_context)
            else: # no_repo
                visible=LineRanges([])
        # syntax detection
        syntax='Plain Text'; unknown=None
        # map syntax parse list already pairs
        syntax,unknown=detect_syntax(spec.detection_path(), reader.first_line_text, explicit=cfg.language, fallback=cfg.fallback, map_syntax=cfg.map_syntax or [], ignored_suffixes=cfg.ignored_suffixes or [], show_all=cfg.show_all)
        if cfg.use_interactive and cfg.colored and unknown is not None:
            raise FatalError(f"unknown syntax: '{unknown}'")
        # theme warning per file (interactive only) after syntax error check
        if cfg.use_interactive and cfg.theme_unknown is not None:
            sys.stderr.write(f"\x1b[33m[bat warning]\x1b[0m: Unknown theme '{cfg.theme_unknown}', using default.\n")
        if cfg.quiet_empty and reader.is_empty:
            return
        if diff_skip:
