            # To match cat-like stdin consumption in multi-input, drain stdin input when skipped? For files irrelevant.
            # We choose not to drain: subsequent '-' would show rest. (may be refined)
            return
        if not cfg.use_interactive:
            self.print_simple(spec,reader,visible)
        else:
            self.print_interactive(spec,reader,visible,first,size,line_changes,syntax)
    # ---------- simple ----------
    def _squeeze_allows(self, is_empty, state):
        # state is dict with 'count'
        if not self.cfg.squeeze:
            return True
        if is_empty:
            state['count']+=1
            return state['count']<=self.cfg.squeeze_limit
        state['count']=0
        return True
    def _is_empty_text(self,text):
        return text.rstrip('\r\n')=='' if False else (text.rstrip('\n').rstrip('\r')=='')
    def _prepare_lines(self,reader,visible):
        """If visible has from-end ranges, read all lines and return list; else return None for streaming."""
        if visible is not None and not visible.is_all and visible.has_from_end():
            return reader.read_all_lines()
        return None
    def print_simple(self,spec,reader,visible):
        cfg=self.cfg
        prepared=self._prepare_lines(reader,visible)
        total=len(prepared) if prepared is not None else None
        state={'count':0}; lineno=0
        idx=0
        while True:
            if prepared is not None:
                if idx>=len(prepared): break
                raw,text,complete=prepared[idx]; idx+=1
            else:
                if cfg.unbuffered and lineno>0 or cfg.unbuffered:
                    item=reader.next_line(unbuffered=cfg.unbuffered)
                else:
                    item=reader.next_line(False)
                if item is None: break
                raw,text,complete=item
            # logical line number only increments for complete lines at their start? Simple chunks: first chunk of a line starts a lineno.
            # Track: if previous chunk was incomplete, this is same line. Prepared lines are complete.
            # For simplicity, increment at start of each complete/raw read when not continuing.
            # We maintain lineno via a flag in local variables using closure trick: use attribute
            lineno=self._next_lineno('simple',complete)
            is_empty=self._line_is_empty_raw(raw,text)
            allow_squeeze=self._squeeze_allows(is_empty,state) if complete else True
            in_range=True
            if visible is not None and not visible.is_all:
                in_range=visible.check(lineno,total)
            self._after_lineno(complete)
            if not in_range or not allow_squeeze:
                continue
            if cfg.show_all:
                out=replace_nonprintable(raw,cfg.tab_width,cfg.notation).encode('utf-8')
                self.write(out)
                if raw.endswith(b'\n'):
                    self.write(b'\n')
            else:
                self.write(raw)
            self.w.flush()
    # line numbering helpers for unbuffered chunks
    _ln_state=None
    def _next_lineno(self,ctx,complete):
        if self._ln_state is None or self._ln_state.get('ctx')!=ctx+str(id(self)):
            # We'll use per-print state stored on self
            pass
        if not hasattr(self,'_cur_lineno'):
            self._cur_lineno=0; self._continuing=False
        if not self._continuing:
            self._cur_lineno+=1
        return self._cur_lineno
    def _after_lineno(self,complete):
        self._continuing=not complete
        if complete:
            # next call increments
            self._continuing=False
        else:
            self._continuing=True
    def _reset_lineno(self):
        self._cur_lineno=0; self._continuing=False
    def _line_is_empty_raw(self,raw,text):
        # text is decoded (for utf16 logical it'll be proper)
        t=text
        if t.endswith('\n'): t=t[:-1]
        if t.endswith('\r'): t=t[:-1]
        return t==''
    # ---------- interactive ----------
    def print_interactive(self,spec,reader,visible,first,size,line_changes,syntax):
        cfg=self.cfg
        self._reset_lineno()
        style=cfg.display_style
        has_header=('header-filename' in style) or ('header-filesize' in style)
        is_binary=(reader.content_kind=='binary')
        is_empty=reader.is_empty
        binary_no_print = is_binary and cfg.binary!='as-text' and not cfg.show_all
        # decorations / panel per file
        decor=[]  # list of (kind,width)
        if not cfg.unbuffered:
            if 'numbers' in style: decor.append(('numbers',4))
            if 'changes' in style and line_changes: decor.append(('changes',1))
            if 'grid' in style and decor: decor.append(('grid',1))
        panel_width=(sum(w for _,w in decor)+len(decor)) if decor else 0
        if decor and cfg.term_width < panel_width+5:
            decor=[]; panel_width=0
        printer=_InteractivePrinter(self,spec,reader,visible,first,size,line_changes,syntax,decor,panel_width,has_header,is_binary,is_empty,binary_no_print)
        printer.run()

class _InteractivePrinter:
    def __init__(self,ctl,spec,reader,visible,first,size,line_changes,syntax,decor,panel_width,has_header,is_binary,is_empty,binary_no_print):
        self.ctl=ctl; self.cfg=ctl.cfg; self.w=ctl.w; self.spec=spec; self.reader=reader; self.visible=visible; self.first=first; self.size=size; self.line_changes=line_changes or {}; self.syntax=syntax or 'Plain Text'; self.decor=decor; self.panel_width=panel_width; self.has_header=has_header; self.is_binary=is_binary; self.is_empty=is_empty; self.binary_no_print=binary_no_print
        self.highlighter=Highlighter(self.syntax, ctl.theme) if self.cfg.colored else None
        self.ansi_state=AnsiState()
        self.strip_effective = (self.cfg.strip_ansi=='always') or (self.cfg.strip_ansi=='auto' and self.syntax!='Plain Text')
    # styling helpers
    def styled(self,prefix,text):
        if not text and not prefix: return ''
        if prefix:
            return prefix+text+'\x1b[0m'
        return text
    def grid_line(self,kind):
        # kind: top|mid|bottom|plain
        w=self.cfg.term_width
        if self.panel_width>0 and kind!='plain':
            # junction at panel_width position (0-indexed panel_width-? panel_width includes trailing space count)
            # Grid horizontal: dashes before junction = panel_width-1? Observed numbers+grid panel_width=7? Wait panel_width here =4+1+2=7, top line is 5 dashes + junction + rest.
            # The junction column is at (panel_width-2) (the grid border column). dashes before = panel_width-2
            jpos=self.panel_width-2
            ch={'top':'┬','mid':'┼','bottom':'┴'}.get(kind,'─')
            line='─'*jpos + ch + '─'*(w-jpos-1) if w>jpos else '─'*w
        else:
            line='─'*w
        if self.cfg.colored:
            gp=self.ctl.theme.grid_prefix
            return self.styled(gp,line)+'\n'
        return line+'\n'
    def panel_prefix_header(self):
        if self.panel_width==0:
            # unbuffered special: if grid in style and colored, reference emits an empty grid-colored segment for STDIN; ignore for now
            return ''
        if any(k=='grid' for k,_ in self.decor):
            spaces=' '*(self.panel_width-2)
            border='│ '
            if self.cfg.colored:
                return spaces+self.styled(self.ctl.theme.grid_prefix,border)
            return spaces+border
        return ' '*self.panel_width
    def header_component(self,text_styled):
        # wrap styled string by char count width = term - panel_width
        w=self.cfg.term_width
        avail=w-self.panel_width
        if avail<=0: avail=w
        prefix=self.panel_prefix_header()
        if avail<=0: avail=1
        # split by Python characters (codepoints)
        chunks=[text_styled[i:i+avail] for i in range(0,len(text_styled),avail)] or ['']
        for ch in chunks:
            self.w.write(prefix+ch+'\n')
    def print_header(self):
        cfg=self.cfg; style=cfg.display_style
        # separator / top
        if 'grid' in style:
            self.w.write(self.grid_line('top'))
        elif 'rule' in style:
            if not self.first:
                self.w.write(self.grid_line('plain'))
        elif self.has_header and not self.first:
            self.w.write('\n')
        # components
        if 'header-filename' in style:
            title,is_stdin=self.spec.header_title_text()
            suffix=''
            if self.is_empty: suffix='   <EMPTY>'
            elif self.is_binary: suffix='   <BINARY>'
            elif self.reader.content_tag: suffix=f'   <{self.reader.content_tag}>'
            if is_stdin:
                text=(f"\x1b[1m{title}\x1b[0m" if cfg.colored else title)+suffix
            else:
                text='File: '+(f"\x1b[1m{title}\x1b[0m" if cfg.colored else title)+suffix
            self.header_component(text)
        if 'header-filesize' in style:
            s=format_size(self.size)
            text='Size: '+(f"\x1b[1m{s}\x1b[0m" if cfg.colored else s)
            self.header_component(text)
        if 'grid' in style and self.has_header:
            if not (self.is_empty or self.binary_no_print):
                self.w.write(self.grid_line('mid'))
    def print_footer(self):
        if 'grid' in self.cfg.display_style:
            self.w.write(self.grid_line('bottom'))
    def run(self):
        cfg=self.cfg; style=cfg.display_style
        # binary no-print without header -> warning instead
        if self.binary_no_print and not self.has_header:
            if 'rule' in style and 'grid' not in style and not self.first:
                self.w.write(self.grid_line('plain'))
            name=self.spec.display_name() if self.spec.kind=='file' else 'STDIN'
            if self.spec.kind=='file':
                msg=f"Binary content from file '{name}' will not be printed to the terminal (but will be present if the output of 'bat' is piped). You can use 'bat -A' to show the binary file contents."
            else:
                msg=f"Binary content from STDIN will not be printed to the terminal (but will be present if the output of 'bat' is piped). You can use 'bat -A' to show the binary file contents."
            self.w.write(f"\x1b[33m[bat warning]\x1b[0m: {msg}\n")
            self.w.flush(); return
        if self.is_empty and not self.has_header:
            return
        self.print_header()
        if not self.is_empty and not self.binary_no_print:
            self.print_lines()
        self.print_footer()
        self.w.flush()
    # panel for content
    def content_prefix(self,lineno,continuation=False,snip=False):
        if not self.decor:
            return ''
        parts=[]
        for kind,w in self.decor:
            if kind=='numbers':
                txt=(' ...' if snip else ('    ' if continuation else f"{lineno:4}"))
                if self.cfg.colored and not snip:
                    parts.append(self.styled(self.ctl.theme.grid_prefix,txt))
                else:
                    parts.append(txt)
            elif kind=='changes':
                if snip or continuation:
                    txt=' '
                    parts.append(txt)
                else:
                    marker=self.line_changes.get(lineno,' ')
                    if self.cfg.colored and marker!=' ':
                        code={'':'','+':'32','~':'33','_':'31','\u203e':'31'}.get(marker,'')
                        parts.append(f"\x1b[{code}m{marker}\x1b[0m" if code else marker)
                    else:
                        parts.append(marker)
            elif kind=='grid':
                txt='│'
                if self.cfg.colored and not snip:
                    parts.append(self.styled(self.ctl.theme.grid_prefix,txt))
                else:
                    parts.append(txt)
        if snip and self.cfg.colored:
            # whole line is styled later; return plain prefix and caller styles entire line
            return ''.join(p+' ' for p in [self._plain_prefix_part(k,lineno,continuation,snip) for k,_ in self.decor])
        return ''.join(p+' ' for p in parts)
    def _plain_prefix_part(self,kind,lineno,continuation,snip):
        if kind=='numbers': return ' ...' if snip else ('    ' if continuation else f"{lineno:4}")
        if kind=='changes': return ' ' if (snip or continuation) else self.line_changes.get(lineno,' ')
        if kind=='grid': return '│'
        return ''
    def panel_display_width(self,lineno=1,continuation=False):
        if not self.decor: return 0
        # actual width may overflow for numbers >=10000
        w=self.panel_width
        if any(k=='numbers' for k,_ in self.decor) and not continuation:
            extra=max(0,len(str(lineno))-4); w+=extra
        return w
    def snip_line(self,lineno):
        cfg=self.cfg
        prefix_plain=''.join(self._plain_prefix_part(k,lineno,False,True)+' ' for k,_ in self.decor)
        panel_w=len(prefix_plain)  # chars (all width1)
        A=cfg.term_width-panel_w
        if A<2:
            content='8<'[:max(0,A)]
        else:
            left=(A-1)//4
            right=(A-2-2*left)//2
            if right<0: right=0
            content=('─ '*left)+'8<'+(' ─'*right)
        line=prefix_plain+content
        if cfg.colored:
            self.w.write(self.styled(self.ctl.theme.grid_prefix,line)+'\n')
        else:
            self.w.write(line+'\n')
    def print_lines(self):
        cfg=self.cfg
        prepared=self.ctl._prepare_lines(self.reader,self.visible)
        total=len(prepared) if prepared is not None else None
        state={'count':0}
        printed_any=False; gap=False
        idx=0; self.ctl._reset_lineno()
        while True:
            if prepared is not None:
                if idx>=len(prepared): break
                raw,text,complete=prepared[idx]; idx+=1
            else:
                item=self.reader.next_line(unbuffered=cfg.unbuffered)
                if item is None: break
                raw,text,complete=item
            lineno=self.ctl._next_lineno('interactive',complete)
            # squeeze calculation only on complete lines / first chunk?
            is_empty=self.ctl._line_is_empty_raw(raw,text)
            allow=self.ctl._squeeze_allows(is_empty,state) if complete else True
            in_range=True
            if self.visible is not None and not self.visible.is_all:
                in_range=self.visible.check(lineno,total)
            self.ctl._after_lineno(complete)
            if not in_range:
                if printed_any: gap=True
                continue
            if not allow:
                continue
            if printed_any and gap and 'snip' in cfg.display_style:
                self.snip_line(lineno)
            gap=False
            self.print_one_line(raw,text,lineno,complete)
            printed_any=True
            self.w.flush()
    def print_one_line(self,raw,text,lineno,complete=True):
        cfg=self.cfg
        # split ending
        ending=''
        body=text
        if body.endswith('\r\n'):
            ending='\r\n'; body=body[:-2]
        elif body.endswith('\n') or body.endswith('\r'):
            ending=body[-1]; body=body[:-1]
        if cfg.show_all:
            display=replace_nonprintable(raw,cfg.tab_width,cfg.notation)
            # display includes symbols for ending chars; body concept for ending is based on raw had \n
        else:
            display=body
            if self.strip_effective:
                display=strip_ansi(display)
            display=expand_tabs(display,cfg.tab_width,0)
        # highlight tokens
        if cfg.colored:
            toks=self.highlighter.highlight(display)
        else:
            toks=[('default',display)] if display else []
        is_highlight=False
        if cfg.highlight_ranges:
            for r in cfg.highlight_ranges:
                lo,up=r.highlight_bounds()
                if lo<=lineno<=up: is_highlight=True; break
        if cfg.wrap_mode=='never':
            self._render_nowrap(toks,lineno,ending,raw,is_highlight)
        elif cfg.wrap_mode=='character':
            self._render_charwrap(toks,lineno,is_highlight)
        elif cfg.wrap_mode=='word':
            self._render_wordwrap(toks,lineno,is_highlight)
        else:
            self._render_nowrap(toks,lineno,ending,raw,is_highlight)
    def _token_prefix(self,slot,is_highlight):
        cfg=self.cfg
        if not cfg.colored and not is_highlight:
            return ''
        theme=self.ctl.theme
        if cfg.colored:
            pref=theme.prefix(slot)
        else:
            pref=theme.prefix(slot) if False else ''
            # when color=never but highlight, foregrounds are omitted but background applies
            pref=''
        if is_highlight:
            bg=theme.highlight_bg
            if bg is None:
                # ansi theme: underline
                if pref:
                    return combine_sgr(['\x1b[4m',pref])
                return '\x1b[4m'
            return combine_sgr([bg,pref]) if pref or bg else bg
        return pref
    def _render_token_text(self,slot,text,is_highlight):
        cfg=self.cfg
        if not cfg.show_all and not self.strip_effective and ('\x1b' in text):
            return self._render_with_retained_ansi(slot,text,is_highlight)
        pref=self._token_prefix(slot,is_highlight)
        return self.styled(pref,text) if pref else text
    def _render_with_retained_ansi(self,slot,text,is_highlight):
        # Only perfectly handles plain-text-like single tokens; for others it still processes.
        pref=self._token_prefix(slot,is_highlight)
        out=[]
        for esc,chunk in ansi_iter(text):
            if esc:
                out.append(chunk); self.ansi_state.update(chunk)
            else:
                if not chunk: continue
                seg=''
                if pref: seg+=pref
                reapp=self.ansi_state.reapply()
                if reapp: seg+=reapp
                seg+=chunk
                if self.ansi_state.hyperlink:
                    seg+='\x1b]8;;\x1b\\'
                if pref: seg+='\x1b[0m'
                out.append(seg)
        return ''.join(out)
    def _highlight_padding(self,used,lineno,continuation=False):
        cfg=self.cfg; theme=self.ctl.theme
        bg=theme.highlight_bg
        if bg is None:
            return '\x1b[4m'
        avail=cfg.term_width-self.panel_display_width(lineno,continuation)
        n=max(0,avail-used)
        return bg+(' '*n)+'\x1b[0m'
    def _render_nowrap(self,toks,lineno,ending,raw,is_highlight):
        cfg=self.cfg
        prefix=self.content_prefix(lineno,False)
        out=[prefix]
        used=0
        for slot,txt in toks:
            out.append(self._render_token_text(slot,txt,is_highlight))
            used+=text_width(strip_ansi(txt))
        if is_highlight:
            out.append(self._highlight_padding(used,lineno))
            if self.ctl.theme.highlight_bg is None:
                # ansi theme leaves underline on then next line will clear? We'll add no reset now except padding handling in caller lines is complex. append nothing
                pass
        self.w.write(''.join(out))
        # line ending
        if not cfg.display_style:
            if cfg.show_all:
                if raw.endswith(b'\n'): self.w.write('\n')
                # ansi highlight reset for ansi theme: reference writes \x1b[24m at start of next line; approximated by writing it after newline of highlighted lines
                if is_highlight and self.ctl.theme.highlight_bg is None: self.w.write('\x1b[24m')
            else:
                self.w.write(ending)
                if is_highlight and self.ctl.theme.highlight_bg is None and ending: self.w.write('\x1b[24m')
        else:
            if cfg.show_all:
                self.w.write('\n')
            else:
                # write \r portion of CRLF then \n; for ending '\r' alone write '\r\n'; for '\n' just '\n'; no ending '\n'
                if ending=='\r\n': self.w.write('\r\n')
                elif ending=='\r': self.w.write('\r\n')
                else: self.w.write('\n')
            if is_highlight and self.ctl.theme.highlight_bg is None:
                self.w.write('\x1b[24m')
    def _render_charwrap(self,toks,lineno,is_highlight):
        cfg=self.cfg
        # flatten to (slot,char) and ANSI escapes in retained text as zero-width pieces attached to current char
        # Build segments
        segments=[]  # list of list of (slot,textfragment,width_of_fragment_chars)
        panel_w=self.panel_display_width(lineno,False)
        cursor=panel_w
        curseg=[]
        def flush_seg():
            segments.append(list(curseg)); curseg.clear()
        for slot,txt in toks:
            # iterate ansi-aware
            for esc,chunk in ansi_iter(txt):
                if esc:
                    curseg.append((slot,chunk,0,True)); continue
                for ch in chunk:
                    if ch=='\t':
                        # retained tab width: approximate as tab stop based on cfg.tab_width or 8? Use char width 1 tentative (refined by tests)
                        wch=1
                    else:
                        wch=char_width(ch)
                    if cursor+wch>cfg.term_width and cursor>panel_w:
                        flush_seg(); cursor=self.panel_display_width(lineno,True)
                    curseg.append((slot,ch,wch,False)); cursor+=wch
        flush_seg()
        if not segments: segments=[[]]
        for si,seg in enumerate(segments):
            prefix=self.content_prefix(lineno,continuation=(si>0))
            self.w.write(prefix)
            # coalesce consecutive same slot non-esc chars into fragments, esc pieces rendered with same rendering logic (they're raw)
            used=sum(w for _,_,w,_ in seg)
            frag_slot=None; frag_chars=[]
            def emit_frag():
                if frag_chars:
                    txt=''.join(frag_chars)
                    self.w.write(self._render_token_text(frag_slot,txt,is_highlight))
                    frag_chars.clear()
            for slot,ch,wch,is_esc in seg:
                if is_esc:
                    emit_frag(); frag_slot=None
                    # raw escape: render through retained logic for a text piece consisting only escape -> out itself + update state
                    self.w.write(self._render_token_text(slot,ch,is_highlight) if False else ch)
                    self.ansi_state.update(ch)
                    continue
                if frag_slot is None: frag_slot=slot
                if slot!=frag_slot:
                    emit_frag(); frag_slot=slot
                frag_chars.append(ch)
            emit_frag()
            if is_highlight and si==len(segments)-1:
                self.w.write(self._highlight_padding(used,lineno,continuation=(si>0)))
            self.w.write('\n')
            if is_highlight and self.ctl.theme.highlight_bg is None and si==len(segments)-1:
                self.w.write('\x1b[24m')
    def _render_wordwrap(self,toks,lineno,is_highlight):
        cfg=self.cfg
        # Build flat char list with slot
        chars=[]
        for slot,txt in toks:
            for esc,chunk in ansi_iter(txt):
                if esc:
                    chars.append((slot,chunk,0,True))
                else:
                    for ch in chunk: chars.append((slot,ch,char_width(ch),False))
        panel_w=self.panel_display_width(lineno,False)
        avail=max(1,cfg.term_width-panel_w)
        plain=''.join(ch for _,ch,w,esc in chars if not esc)
        # Use Python textwrap to compute segment boundaries in terms of indices into plain chars (ignoring esc pieces for now)
        import textwrap as _tw
        wrapper=_tw.TextWrapper(width=avail,break_long_words=True,break_on_hyphens=False,expand_tabs=False,replace_whitespace=False,drop_whitespace=False)
        lines=wrapper.wrap(plain) if plain else ['']
        # textwrap may drop / change spaces; if concatenated lines != plain, fall back to character word(ish) segmentation by indices greedy.
        if ''.join(lines)!=plain:
            lines=_word_wrap_plain(plain,avail)
        # map line boundaries to chars
        idx=0; segments=[]
        # create list of non-esc entries with cumulative
        entries=[]; 
        for e in chars:
            entries.append(e)
        pos_plain=0
        seg=[]
        lines_remaining=lines[:]
        # iterate entries, cut after consuming len(line) plain chars
        cur_target=len(lines_remaining[0]) if lines_remaining else 0
        cur_count=0
        for e in entries:
            seg.append(e)
            if not e[3]:
                cur_count+=1
                if cur_count>=cur_target and len(lines_remaining)>1:
                    segments.append(seg); seg=[]; lines_remaining.pop(0); cur_target=len(lines_remaining[0]); cur_count=0
        segments.append(seg)
        for si,seg in enumerate(segments):
            prefix=self.content_prefix(lineno,continuation=(si>0))
            self.w.write(prefix)
            frag_slot=None; frag=[]
            used=sum(w for _,_,w,_ in seg)
            def emit():
                if frag:
                    self.w.write(self._render_token_text(frag_slot,''.join(frag),is_highlight)); frag.clear()
            for slot,ch,wch,is_esc in seg:
                if is_esc:
                    emit(); frag_slot=None; self.w.write(ch); self.ansi_state.update(ch); continue
                if frag_slot is None: frag_slot=slot
                if slot!=frag_slot: emit(); frag_slot=slot
                frag.append(ch)
            emit()
            if is_highlight and si==len(segments)-1:
                self.w.write(self._highlight_padding(used,lineno,continuation=(si>0)))
            self.w.write('\n')
            if is_highlight and self.ctl.theme.highlight_bg is None and si==len(segments)-1:
                self.w.write('\x1b[24m')

def _word_wrap_plain(text,avail):
    if avail<=0: avail=1
    lines=[]; i=0
    while i<len(text):
        if len(text)-i<=avail: # width approx chars count (unicode width ignored here)
            lines.append(text[i:]); break
        # find last space within avail+1
        window=text[i:i+avail+1]
        cut=window.rfind(' ')
        if cut<=0:
            lines.append(text[i:i+avail]); i+=avail
        else:
            lines.append(text[i:i+cut+1]); i+=cut+1
    return lines or ['']

