class FdSource:
    """Buffered raw line source over an fd for stdin (shared)."""
    def __init__(self,fd):
        self.fd=fd; self.buf=bytearray(); self.eof=False
    def _fill(self):
        if self.eof: return False
        try: chunk=os.read(self.fd,8192)
        except BlockingIOError: return False
        if not chunk:
            self.eof=True; return False
        self.buf+=chunk; return True
    def readline(self):
        while b'\n' not in self.buf and not self.eof:
            if not self._fill(): break
        if b'\n' in self.buf:
            idx=self.buf.index(b'\n')+1
            out=bytes(self.buf[:idx]); del self.buf[:idx]; return out
        out=bytes(self.buf); self.buf.clear(); return out
    def readall(self):
        parts=[bytes(self.buf)]; self.buf.clear()
        while not self.eof:
            try: chunk=os.read(self.fd,65536)
            except Exception: break
            if not chunk: self.eof=True; break
            parts.append(chunk)
        return b''.join(parts)
    def readline_unbuffered(self):
        # returns (bytes, is_complete)
        if b'\n' in self.buf:
            idx=self.buf.index(b'\n')+1; out=bytes(self.buf[:idx]); del self.buf[:idx]; return out,True
        if self.eof:
            out=bytes(self.buf); self.buf.clear(); return out,True
        # block for first chunk
        try:
            chunk=os.read(self.fd,8192)
        except BlockingIOError:
            chunk=b''
        if not chunk:
            self.eof=True; out=bytes(self.buf); self.buf.clear(); return out,True
        self.buf+=chunk
        # drain what's immediately available (nonblocking)
        import fcntl, select
        while b'\n' not in self.buf:
            r,_,_=select.select([self.fd],[],[],0)
            if not r: break
            try: chunk=os.read(self.fd,8192)
            except BlockingIOError: break
            if not chunk:
                self.eof=True; break
            self.buf+=chunk
        if b'\n' in self.buf:
            idx=self.buf.index(b'\n')+1; out=bytes(self.buf[:idx]); del self.buf[:idx]; return out,True
        out=bytes(self.buf); self.buf.clear(); return out,False

class FileSource:
    def __init__(self,fp):
        self.fp=fp
    def readline(self):
        return self.fp.readline()
    def readall(self):
        return self.fp.read()
    def readline_unbuffered(self):
        # For regular files/files in general: read a complete line.
        # For fifos, fp.readline blocks until newline/EOF which defeats unbuffered; use fd logic if possible.
        try:
            fd=self.fp.fileno()
        except Exception:
            return self.fp.readline(),True
        # If it's a regular file, readline is fine.
        try:
            if stat.S_ISREG(os.fstat(fd).st_mode):
                return self.fp.readline(),True
        except Exception:
            pass
        # Fallback: use buffered fp readline (acceptable)
        return self.fp.readline(),True

def classify_content(first_raw):
    if not first_raw:
        return ('empty',None)
    if first_raw.startswith(b'\xff\xfe\x00\x00'):
        return ('utf32le',None)
    if first_raw.startswith(b'\x00\x00\xfe\xff'):
        return ('utf32be',None)
    if first_raw.startswith(b'\xef\xbb\xbf'):
        return ('utf8bom',None)
    if first_raw.startswith(b'\xff\xfe'):
        return ('utf16le','UTF-16LE')
    if first_raw.startswith(b'\xfe\xff'):
        return ('utf16be','UTF-16BE')
    if b'\x00' in first_raw[:1024]:
        return ('binary','BINARY')
    return ('utf8',None)

class Reader:
    def __init__(self, source, interactive, show_all):
        self.source=source
        self.first_raw=source.readline()
        self.is_empty=(self.first_raw==b'')
        self.content_kind,self.content_tag=classify_content(self.first_raw)
        self._first_used=False
        self._logical_lines=None
        self._logical_idx=0
        # decoded first line (for syntax detection) best effort
        self.first_line_text=self._decode_first_for_detect()
        if interactive and not show_all and self.content_kind in ('utf16le','utf16be'):
            # slurp rest & decode logically
            rest=b''
            try: rest=source.readall()
            except Exception: rest=b''
            full=self.first_raw+rest
            enc='utf-16le' if self.content_kind=='utf16le' else 'utf-16be'
            data=full[2:] if len(full)>=2 else b''
            text=data.decode(enc,errors='replace')
            # split by \n only retaining ends
            lines=[]
            parts=text.split('\n')
            for p in parts[:-1]: lines.append(p+'\n')
            if parts[-1]: lines.append(parts[-1])
            if not lines and full:
                lines=['']
            self._logical_lines=lines
            self.first_line_text=lines[0] if lines else ''
    def _decode_first_for_detect(self):
        raw=self.first_raw
        if self.content_kind=='utf8bom' and raw.startswith(b'\xef\xbb\xbf'):
            raw=raw[3:]
        if self.content_kind in ('utf16le','utf16be'):
            enc='utf-16le' if self.content_kind=='utf16le' else 'utf-16be'
            try: return raw[2:].decode(enc,errors='replace')
            except Exception: return raw.decode('utf-8',errors='replace')
        return raw.decode('utf-8',errors='replace')
    def decode_raw(self, raw, is_first=False):
        if is_first and self.content_kind=='utf8bom' and raw.startswith(b'\xef\xbb\xbf'):
            raw=raw[3:]
        return raw.decode('utf-8',errors='replace')
    def __iter__(self):
        return self
    def __next__(self):
        item=self.next_line()
        if item is None: raise StopIteration
        return item
    def next_line(self, unbuffered=False):
        """Return (raw_bytes, decoded_text, is_complete) or None at EOF."""
        if self._logical_lines is not None:
            if self._logical_idx>=len(self._logical_lines): return None
            t=self._logical_lines[self._logical_idx]; self._logical_idx+=1
            return (t.encode('utf-8','replace'), t, True)
        if not self._first_used:
            self._first_used=True
            if self.first_raw==b'':
                return None
            return (self.first_raw, self.decode_raw(self.first_raw,True), self.first_raw.endswith(b'\n') or True)
        # Note: first line is always a complete raw line per readline
        if unbuffered:
            raw,complete=self.source.readline_unbuffered()
        else:
            raw=self.source.readline(); complete=True
        if raw==b'':
            return None
        return (raw, self.decode_raw(raw,False), complete)
    def read_all_lines(self):
        lines=[]
        while True:
            it=self.next_line(False)
            if it is None: break
            lines.append(it)
        return lines

