def _word_wrap_plain(text,avail):
    if avail<=0: avail=1
    lines=[]; i=0
    while i<len(text):
        if len(text)-i<=avail: # width approx chars count (unicode width ignored here)
            lines.append(text[i:]); break
        # find last space within avail+1
        window=text[i:i+avail+1]
        cut=window.rfind(' ')
        if cut<=0:
            lines.append(text[i:i+avail]); i+=avail
        else:
            lines.append(text[i:i+cut+1]); i+=cut+1
    return lines or ['']

