def classify_content(first_raw):
    if not first_raw:
        return ('empty',None)
    if first_raw.startswith(b'\xff\xfe\x00\x00'):
        return ('utf32le',None)
    if first_raw.startswith(b'\x00\x00\xfe\xff'):
        return ('utf32be',None)
    if first_raw.startswith(b'\xef\xbb\xbf'):
        return ('utf8bom',None)
    if first_raw.startswith(b'\xff\xfe'):
        return ('utf16le','UTF-16LE')
    if first_raw.startswith(b'\xfe\xff'):
        return ('utf16be','UTF-16BE')
    if b'\x00' in first_raw[:1024]:
        return ('binary','BINARY')
    return ('utf8',None)

