    if x: return os.path.join(x,'bat')
    return os.path.join(home_dir(),'.cache','bat')

# terminal scheme query
_query_cache={'done':False,'result':None,'count':0}
def query_terminal_scheme(force_again=False):
    if _query_cache['done'] and not force_again:
        return _query_cache['result']
    _query_cache['done']=True
    term=os.environ.get('TERM')
    if not term or term=='dumb':
        _query_cache['result']=None; return None
    # choose tty fd
    fd=None; close_fd=False; target=None
    try:
        if sys.stdout.isatty():
            try:
                target=os.ttyname(1); fd=os.open(target, os.O_RDWR|os.O_NOCTTY); close_fd=True
            except Exception:
                fd=1
        else:
            try:
                fd=os.open('/dev/tty', os.O_RDWR|os.O_NOCTTY); close_fd=True
            except Exception:
                _query_cache['result']=None; return None
        # set raw-ish on fd if tty
        import termios, select
        old=None
        try:
            old=termios.tcgetattr(fd)
            new=termios.tcgetattr(fd)
            new[3] = new[3] & ~(termios.ICANON|termios.ECHO)
            new[6][termios.VMIN]=0; new[6][termios.VTIME]=1
            termios.tcsetattr(fd, termios.TCSANOW, new)
        except Exception:
            old=None
        try:
            os.write(fd, b'\x1b]10;?\x07\x1b]11;?\x07\x1b[c')
            data=b''; end=time.time()+0.15
            while time.time()<end:
                r,_,_=select.select([fd],[],[],max(0,end-time.time()))
                if not r: break
                try: chunk=os.read(fd,1024)
                except Exception: break
                if not chunk: break
                data+=chunk
                if b'\x1b[' in data: 
                    # DA response is CSI ... c
                    if b'c' in data.split(b'\x1b[',1)[-1]: break
        finally:
            if old is not None:
                try: termios.tcsetattr(fd, termios.TCSANOW, old)
                except Exception: pass
        # parse OSC 11 rgb
        import re
        m=re.search(rb'\]11;rgb:([0-9a-fA-F]+)/([0-9a-fA-F]+)/([0-9a-fA-F]+)',data)
        if not m:
            m=re.search(rb'\]11;rgb:([0-9a-fA-F]+)/([0-9a-fA-F]+)/([0-9a-fA-F]+)',data)
        if m:
            vals=[]
            for g in m.groups():
                v=int(g.decode(),16); maxv=(1<<(4*len(g)))-1; vals.append(v/maxv if maxv else 0)
            lum=0.2126*vals[0]+0.7152*vals[1]+0.0722*vals[2]
            res='light' if lum>0.5 else 'dark'
            _query_cache['result']=res; return res
        _query_cache['result']=None; return None
    except Exception:
        _query_cache['result']=None; return None
    finally:
        if close_fd and fd is not None and fd>2:
            try: os.close(fd)
            except Exception: pass

def resolve_theme(parsed,is_tty):
    """return (effective_theme_name, unknown_name_or_None, scheme)"""
    theme_opt=parsed.get_last('theme',None)
    dark_opt=parsed.get_last('theme-dark',None)
    light_opt=parsed.get_last('theme-light',None)
    default_dark='Monokai Extended'; default_light='Monokai Extended Light'
    scheme=None; selected=None
    if theme_opt is None or theme_opt=='' or theme_opt in ('auto','auto:always','auto:system'):
        # auto
        if theme_opt!='auto:system':
            if theme_opt=='auto:always' or is_tty:
                scheme=query_terminal_scheme()
        if scheme=='light':
            selected=light_opt or default_light
        elif scheme=='dark':
            selected=dark_opt or default_dark
        else:
            selected=default_dark
    elif theme_opt=='dark':
        scheme='dark'; selected=dark_opt or default_dark
    elif theme_opt=='light':
        scheme='light'; selected=light_opt or default_light
    else:
        selected=theme_opt
    unknown=None
    # custom themes loaded (later) may add names: check global custom set populated by load_custom_assets
    known=set(THEMES)|getattr(resolve_theme,'custom_names',set())
    effective=selected
    if selected not in known:
        unknown=selected; effective=default_dark
    return effective,unknown,scheme

