# config text parsing
def parse_config_text(text,source):
    toks=[]
    for line in text.splitlines():
        try:
            parts=shell_split(line)
        except Exception:
            raise BatFatal('Could not parse configuration file')
        for p in parts: toks.append(Token(p,source))
    return toks
