def load_config_tokens(no_config):
    if no_config:
        return []
    if 'BAT_OPTS' in os.environ:
        txt=os.environ.get('BAT_OPTS','')
        return parse_config_text(txt,'batopts')
    toks=[]
    for path,src in [('/etc/bat/config','config'),(config_file_path(),'config')]:
        try:
            with open(path,'r',encoding='utf-8') as f: txt=f.read()
        except Exception:
            continue
        toks.extend(parse_config_text(txt,src))
    return toks

def env_tokens():
