# ---------- resolution from Parsed ----------
STYLE_ALL=frozenset({'changes','header-filename','header-filesize','grid','rule','numbers','snip'})
STYLE_DEFAULT=frozenset({'changes','grid','header-filename','numbers','snip'})
def expand_style_name(name,is_tty):
    if name=='plain': return set()
    if name=='auto': return set(STYLE_DEFAULT) if is_tty else set()
    if name=='default': return set(STYLE_DEFAULT)
    if name=='full': return set(STYLE_ALL)
    if name=='header': return {'header-filename'}
    return {name}
def resolve_styles(parsed,is_tty):
    vals=parsed.get_all('style')
    if not vals: return None
    cur=set()
    for s in vals:
        comps=s.split(',')
        pure=all(c[:1] in ('+','-') for c in comps)
        if not pure:
            cur=set()
        for c in comps:
            if c[:1]=='-':
                cur-=expand_style_name(c[1:],is_tty)
            elif c[:1]=='+':
                cur|=expand_style_name(c[1:],is_tty)
            else:
                cur|=expand_style_name(c,is_tty)
    return frozenset(cur)

def terminal_actual_width():
    try:
        if sys.stdout.isatty():
            sz=os.get_terminal_size(1)
            if sz.columns>0: return sz.columns
    except Exception: pass
    return 80

class Resolved:
    pass

def resolve_config(parsed, prog, original_cli):
    r=Resolved(); r.parsed=parsed
    r.is_tty=False
    try: r.is_tty=sys.stdout.isatty()
    except Exception: pass
    r.has_n_cli=any((t=='--number' or (t.startswith('-') and not t.startswith('--') and 'n' in t[1:])) for t in original_cli)
    # paging sequential and plain count
    paging='auto'; plain_count=0
    for o in parsed.occ:
        if o.id=='paging': paging=o.value
        elif o.id=='no-paging': paging='never'
        elif o.id=='plain':
            plain_count+=1
            if plain_count==2: paging='never'
    r.paging=paging; r.plain_count=plain_count
    # plain/number final
    final=None
    for o in parsed.occ:
        if o.id=='plain': final='plain'
        elif o.id=='number': final='number'
    r.plain_number_final=final
    r.color_when=parsed.get_last('color','auto')
    if parsed.has('force-colorization'): r.color_when='always'
    r.decor_when=parsed.get_last('decorations','auto')
    if parsed.has('force-colorization'): r.decor_when='always'
    no_color_env=('NO_COLOR' in os.environ and os.environ.get('NO_COLOR','')!='')
    r.colored=(r.color_when=='always') or (r.color_when=='auto' and r.is_tty and not no_color_env)
    r.use_decor=(r.decor_when=='always') or (r.decor_when=='auto' and (r.is_tty or r.colored or r.has_n_cli))
    r.use_interactive=r.is_tty or r.colored or r.use_decor
    r.use_pager=(paging=='always') or (paging=='auto' and r.is_tty)
    # styles
    resolved=resolve_styles(parsed,r.is_tty)
    if not r.use_decor:
        display=frozenset()
    elif final=='plain': display=frozenset()
    elif final=='number': display=frozenset({'numbers'})
    elif resolved is None: display=STYLE_DEFAULT
    else: display=resolved
    r.display_style=display
    # term width
    r.actual_width=terminal_actual_width()
    twvals=parsed.get_all('terminal-width')
    r.term_explicit=bool(twvals)
    if twvals:
        kind,v=twvals[-1]
        if kind=='abs': r.term_width=v
        else:
            cand=r.actual_width+v; r.term_width=cand if cand>0 else r.actual_width
    else:
        r.term_width=r.actual_width
    # wrap
    wrapv=parsed.get_last('wrap','auto')
    if parsed.has('chop-long-lines'): r.wrap_mode='never'; r.wrap_explicit_never=True
    elif wrapv in ('character','word','never'): r.wrap_mode=wrapv; r.wrap_explicit_never=(wrapv=='never')
    else: r.wrap_mode='character' if (r.is_tty or r.term_explicit) else 'never'; r.wrap_explicit_never=False
    # tabs
    tabvals=parsed.get_all('tabs')
    if tabvals: r.tab_width=tabvals[-1]
    else: r.tab_width=0 if (not display and not r.use_pager) else 4
    # ranges
    try:
        lr=[parse_line_range(x) for x in parsed.get_all('line-range')]
    except RangeError as e: raise BatFatal(str(e))
    r.line_ranges=LineRanges(lr) if lr else LineRanges(None)
    try:
        r.highlight_ranges=[parse_line_range(x) for x in parsed.get_all('highlight-line')]
    except RangeError as e: raise BatFatal(str(e))
    # map syntax
    r.map_syntax=[]
    for x in parsed.get_all('map-syntax'):
        parts=x.split(':')
        if len(parts)!=2:
            raise BatFatal("Invalid syntax mapping. The format of the -m/--map-syntax option is '<glob-pattern>:<syntax-name>'. For example: '*.cpp:C++'.")
        r.map_syntax.append((parts[0],parts[1]))
    # theme (also triggers terminal query)
    r.theme_name,r.theme_unknown,r.scheme=resolve_theme(parsed,r.is_tty)
    r.truecolor=os.environ.get('COLORTERM') in ('truecolor','24bit')
    return r

