# ---------- pager ----------
class PagerOutput:
    def __init__(self):
        self.proc=None; self.fp=sys.stdout.buffer; self.builtin=False; self.builtin_buf=None
    def close(self):
        if self.builtin:
            try:
                import builtin_pager
                builtin_pager.run(self.builtin_buf.getvalue() if self.builtin_buf else b'')
            except Exception:
                pass
            return
        if self.proc is not None:
            try: self.proc.stdin.close()
            except Exception: pass
            try: self.proc.wait()
            except Exception: pass

