    return None

def open_pager(r, inputs_titles):
    out=PagerOutput()
    if not r.use_pager:
        return out
    parsed=r.parsed
    # determine command
    source='default'; cmd='less'
    pager_occs=[o for o in parsed.occ if o.id=='pager']
    if pager_occs:
        cmd=pager_occs[-1].value; source='cmdline'
    elif 'BAT_PAGER' in os.environ:
        cmd=os.environ['BAT_PAGER']; source='bat_pager'
    elif 'PAGER' in os.environ:
        cmd=os.environ['PAGER']; source='pager_env'
    if cmd is None or cmd.strip()=='':
        return out
    try:
        words=shell_split(cmd)
    except Exception:
        raise BatFatal('Could not parse pager command.')
    if not words:
        return out
    if words==['builtin']:
        out.builtin=True
        import io; out.builtin_buf=io.BytesIO(); out.fp=out.builtin_buf
        if parsed.has('set-terminal-title'):
            title=', '.join(inputs_titles)
            try: sys.stdout.buffer.write(f"\x1b]0;bat: {title}\x07".encode()); sys.stdout.buffer.flush()
            except Exception: pass
        return out
    binary=words[0]; user_args=words[1:]
    is_less=os.path.basename(binary)=='less'
    args=list(user_args)
    env=dict(os.environ)
    if is_less:
        env['LESSCHARSET']='UTF-8'
        use_default_args=False
        if source=='default': use_default_args=True
        elif source=='pager_env': use_default_args=True
        elif not user_args: use_default_args=True
        if use_default_args:
            args=['-R']
            quit_one=(r.paging=='auto' and r.is_tty)
            if quit_one: args.append('-F')
            if getattr(r,'wrap_explicit_never',False): args.append('-S')
            args.append('-K')
            if quit_one: args.append('--no-init')
    # resolve binary
    resolved=None
    if '/' in binary:
        if os.path.isfile(binary) and os.access(binary,os.X_OK): resolved=binary
    else:
        resolved=shutil.which(binary)
    proc=None
    if resolved:
        try:
            proc=subprocess.Popen([resolved]+args,stdin=subprocess.PIPE,stdout=sys.stdout,stderr=sys.stderr,env=env)
        except Exception:
            proc=None
    if proc is None:
        sys.stderr.write(f"\x1b[33m[bat warning]\x1b[0m: Pager '{binary}' not found, outputting to stdout instead\n")
        return out
    out.proc=proc; out.fp=proc.stdin
    if parsed.has('set-terminal-title'):
        title=', '.join(inputs_titles)
        try: out.fp.write(f"\x1b]0;bat: {title}\x07".encode())
        except Exception: pass
    return out

# ---------- special printing through pager for help/list ----------
def output_via_pager(r, titles, generate_fn):
    pager=open_pager(r,titles)
    w=Writer(pager.fp)
    try:
        generate_fn(w)
        w.flush()
    finally:
        pager.close()

def highlight_text_block(text, syntax_name, r, force_truecolor=False):
    # returns bytes highlighted line-by-line plain style
    theme=Theme(r.theme_name, True if force_truecolor else r.truecolor, r.parsed.get_last('italic-text','never')=='always')
    hl=Highlighter(syntax_name,theme)
    out=[]
    lines=text.split('\n')
    # text ends with \n usually; split handling: if text ends with \n, last element '' should not produce extra line
    has_final=text.endswith('\n')
    if has_final: lines=lines[:-1]
    for line in lines:
        toks=hl.highlight(line) if line else []
        s=''
        for slot,txt in toks:
            pref=theme.prefix(slot)
            s+= (pref+txt+'\x1b[0m' if pref else txt)
        out.append(s+'\n')
    return ''.join(out).encode()

def do_help(r, kind):
