def run_cache(tokens, prog):
    parser=Parser(CACHE_SPECS,prog,is_cache=True,conflicts=CACHE_CONFLICTS)
    try:
        parsed=parser.parse(tokens)
    except CacheHelpAction as h:
        tmpl=CACHE_HELP_LONG_TMPL if h.long else CACHE_HELP_SHORT_TMPL
        sys.stdout.write(tmpl.decode().replace('{prog}',prog)); return 0
    except ClapError as e:
        if e.kind=='cache_noargs':
            sys.stderr.write(CACHE_HELP_SHORT_TMPL.decode().replace('{prog}',prog)); return 2
        raise
