def run(argv):
    prog=os.path.basename(argv[0]) if argv and argv[0] else 'bat'
    original_cli=list(argv[1:])
    # cache candidate from original CLI
    if original_cli and original_cli[0]=='cache' and not os.path.exists('cache'):
        return run_cache([Token(t,'cli') for t in original_cli[1:]], prog)
    # help/version candidate detection (raw token scan)
    has_help_candidate=any(t in ('-h','--help') or (t.startswith('-') and not t.startswith('--') and 'h' in t[1:]) for t in original_cli)
    has_version_candidate=any(t in ('-V','--version') or (t.startswith('-') and not t.startswith('--') and 'V' in t[1:]) for t in original_cli)
    parser=Parser(MAIN_SPECS,prog,is_cache=False,conflicts=MAIN_CONFLICTS)
    prelim=None; prelim_help_kind=None
    if has_help_candidate or has_version_candidate:
        # may raise VersionAction / ClapError
        prelim=parser.parse([Token(t,'cli') for t in original_cli])
        prelim_help_kind=prelim.help_kind
        if prelim_help_kind is None and not has_version_candidate:
            prelim=None
    no_config=('--no-config' in original_cli)
    # If prelim help: try merged best effort
    parsed=None
    if prelim is not None and prelim_help_kind is not None:
        try:
            cfg_toks=load_config_tokens(no_config)
            merged=cfg_toks+env_tokens()+[Token(t,'cli') for t in original_cli]
            parsed=parser.parse(merged)
            # if merged help kind differs, force prelim kind
            parsed.help_kind=prelim_help_kind
        except VersionAction:
            parsed=prelim
        except Exception:
            parsed=prelim
    else:
        cfg_toks=load_config_tokens(no_config)
        merged=cfg_toks+env_tokens()+[Token(t,'cli') for t in original_cli]
        if merged and merged[0].text=='cache' and not os.path.exists('cache'):
            return run_cache(merged[1:], prog)
        parsed=parser.parse(merged)
        if parsed.help_kind is not None and prelim_help_kind is None:
            # help only from config/batopts -> short
            parsed.help_kind='short'
    # file-name count check done in normal print path after resolving config? Reference errors before theme query? will check later.
    # completion handled before theme query/config resolution
    if parsed.has('completion'):
        shell=parsed.get_last('completion')
        sys.stdout.write(COMPLETIONS.get(shell,''))
        return 0
    r=resolve_config(parsed,prog,original_cli)
    # custom assets check for most modes except some trivial path printers? Reference checks even for --config-file? We'll check for print/list/help/ack modes below as needed.
    if parsed.help_kind is not None:
        # help uses assets; check
        check_custom_assets()
        return do_help(r, parsed.help_kind)
    if parsed.has('diagnostic'):
        return do_diagnostic(r, argv)
    if parsed.has('list-languages'):
        check_custom_assets(); return do_list_languages(r)
    if parsed.has('list-themes'):
        check_custom_assets(); return do_list_themes(r)
    if parsed.has('config-file'):
        sys.stdout.write(config_file_path()+'\n'); return 0
    if parsed.has('generate-config-file'):
        return do_generate_config()
    if parsed.has('config-dir'):
        sys.stdout.write(config_dir()+'\n'); return 0
    if parsed.has('cache-dir'):
        sys.stdout.write(cache_dir_path()+'\n'); return 0
    if parsed.has('acknowledgements'):
        check_custom_assets()
        # custom acknowledgements.bin handling later
        sys.stdout.buffer.write(ACKNOWLEDGEMENTS); return 0
    # normal printing
    check_custom_assets()
    # build inputs
    files=parsed.files
    file_names=parsed.get_all('file-name')
    inputs=[]
    if not files:
        inputs=[InputSpec('stdin')]
    else:
        for f in files:
            if f=='-': inputs.append(InputSpec('stdin'))
            else: inputs.append(InputSpec('file',path=f))
    if file_names:
        if len(file_names)!=len(inputs):
            raise BatFatal('Must be one file name per input type.')
        for inp,fn in zip(inputs,file_names): inp.title=fn
