    titles=[]
    for inp in inputs:
        if inp.kind=='stdin' and inp.title is None: titles.append('STDIN')
        else: titles.append(inp.display_name())
    printcfg=make_print_config(r)
    pager=open_pager(r,titles)
    writer=Writer(pager.fp)
    ctl=Controller(printcfg,writer)
    try:
        code=ctl.run(inputs)
    finally:
        pager.close()
