def main():
    argv=sys.argv
    try:
        code=run(argv)
    except VersionAction:
        sys.stdout.write(BAT_VERSION+'\n'); code=0
    except ClapError as e:
        if e.kind=='cache_noargs':
            # handled in run_cache normally
            code=2
        else:
            text=e.text
