    p.theme_name=r.theme_name; p.theme_unknown=r.theme_unknown; p.quiet_empty=r.parsed.has('quiet-empty'); p.unbuffered=r.parsed.has('unbuffered')
    return p

# ---------- pager ----------
class PagerOutput:
    def __init__(self):
        self.proc=None; self.fp=sys.stdout.buffer; self.builtin=False; self.builtin_buf=None
    def close(self):
        if self.builtin:
            try:
                import builtin_pager
                builtin_pager.run(self.builtin_buf.getvalue() if self.builtin_buf else b'')
            except Exception:
                pass
            return
        if self.proc is not None:
            try: self.proc.stdin.close()
            except Exception: pass
            try: self.proc.wait()
            except Exception: pass

def get_less_version(binary):
    return None

def open_pager(r, inputs_titles):
    out=PagerOutput()
    if not r.use_pager:
        return out
    parsed=r.parsed
    # determine command
    source='default'; cmd='less'
    pager_occs=[o for o in parsed.occ if o.id=='pager']
    if pager_occs:
        cmd=pager_occs[-1].value; source='cmdline'
    elif 'BAT_PAGER' in os.environ:
        cmd=os.environ['BAT_PAGER']; source='bat_pager'
    elif 'PAGER' in os.environ:
        cmd=os.environ['PAGER']; source='pager_env'
    if cmd is None or cmd.strip()=='':
        return out
    try:
        words=shell_split(cmd)
    except Exception:
        raise BatFatal('Could not parse pager command.')
    if not words:
        return out
    if words==['builtin']:
        out.builtin=True
        import io; out.builtin_buf=io.BytesIO(); out.fp=out.builtin_buf
        if parsed.has('set-terminal-title'):
            title=', '.join(inputs_titles)
            try: sys.stdout.buffer.write(f"\x1b]0;bat: {title}\x07".encode()); sys.stdout.buffer.flush()
            except Exception: pass
        return out
    binary=words[0]; user_args=words[1:]
    is_less=os.path.basename(binary)=='less'
    args=list(user_args)
    env=dict(os.environ)
    if is_less:
        env['LESSCHARSET']='UTF-8'
        use_default_args=False
        if source=='default': use_default_args=True
        elif source=='pager_env': use_default_args=True
        elif not user_args: use_default_args=True
        if use_default_args:
            args=['-R']
            quit_one=(r.paging=='auto' and r.is_tty)
            if quit_one: args.append('-F')
            if getattr(r,'wrap_explicit_never',False): args.append('-S')
            args.append('-K')
            if quit_one: args.append('--no-init')
    # resolve binary
    resolved=None
    if '/' in binary:
        if os.path.isfile(binary) and os.access(binary,os.X_OK): resolved=binary
    else:
        resolved=shutil.which(binary)
    proc=None
    if resolved:
        try:
            proc=subprocess.Popen([resolved]+args,stdin=subprocess.PIPE,stdout=sys.stdout,stderr=sys.stderr,env=env)
        except Exception:
            proc=None
    if proc is None:
        sys.stderr.write(f"\x1b[33m[bat warning]\x1b[0m: Pager '{binary}' not found, outputting to stdout instead\n")
        return out
    out.proc=proc; out.fp=proc.stdin
    if parsed.has('set-terminal-title'):
        title=', '.join(inputs_titles)
        try: out.fp.write(f"\x1b]0;bat: {title}\x07".encode())
        except Exception: pass
    return out

# ---------- special printing through pager for help/list ----------
def output_via_pager(r, titles, generate_fn):
    pager=open_pager(r,titles)
    w=Writer(pager.fp)
    try:
        generate_fn(w)
        w.flush()
    finally:
        pager.close()

def highlight_text_block(text, syntax_name, r, force_truecolor=False):
    # returns bytes highlighted line-by-line plain style
    theme=Theme(r.theme_name, True if force_truecolor else r.truecolor, r.parsed.get_last('italic-text','never')=='always')
    hl=Highlighter(syntax_name,theme)
    out=[]
    lines=text.split('\n')
    # text ends with \n usually; split handling: if text ends with \n, last element '' should not produce extra line
    has_final=text.endswith('\n')
    if has_final: lines=lines[:-1]
    for line in lines:
        toks=hl.highlight(line) if line else []
        s=''
        for slot,txt in toks:
            pref=theme.prefix(slot)
            s+= (pref+txt+'\x1b[0m' if pref else txt)
        out.append(s+'\n')
    return ''.join(out).encode()

def do_help(r, kind):
    text=(HELP_LONG if kind=='long' else HELP_SHORT).decode()
    def gen(w):
        if r.colored:
            w.write(highlight_text_block(text,'Command Help',r,force_truecolor=True))
        else:
            w.write(text.encode())
    output_via_pager(r,['STDIN'],gen)
    return 0

def do_list_languages(r):
    langs=languages_for_listing()
    def gen(w):
        if not r.colored:
            for name,exts in langs:
                w.write(f"{name}:{','.join(exts)}\n")
        else:
            w.write(format_languages_colored(langs,r.term_width))
    output_via_pager(r,['STDIN'],gen)
    return 0

def format_languages_colored(langs,term_width):
    maxlen=max(len(n) for n,_ in langs)
    col=maxlen+1
    out=[]
    for name,exts in langs:
        # styled extensions: green double as in reference (due ANSI processing)
        def ge(e): return f"\x1b[32m\x1b[32m{e}\x1b[0m"
        ext_text_plain=', '.join(exts)
        # wrap plain text with textwrap-ish greedy at width, indent col
        # Build full plain line then wrap by words/extensions
        # We wrap ext_text_plain into chunks fitting term_width-col, breaking after ', ' mostly
        avail=max(10,term_width-col)
        chunks=[]; cur=''
        for e in exts:
            piece=e if cur=='' else ', '+e
            # Reference wraps keeping trailing comma+space at line end when next doesn't fit
            if cur and len(cur)+len(piece) > avail:
                # check if adding ', ' fits? Reference lines end with ', ' when wrapping
                chunks.append(cur+', '); cur=e
            else:
                cur+=piece
        chunks.append(cur)
        for idx,ch in enumerate(chunks):
            # style each ext in chunk: split by ', '
            # Rebuild styled from exts segment -- simpler: style by replacing each ext name in order (names unique enough but regex escape)
            styled=ch
            # We need to know which exts are in this chunk: parse by stripping trailing ', '
            core=ch[:-2] if ch.endswith(', ') else ch
            parts=core.split(', ') if core else []
            styled=', '.join(ge(p) for p in parts)
            if ch.endswith(', '): styled+=', '
            prefix=name.ljust(col) if idx==0 else ' '*col
            out.append(prefix+styled+'\n')
    return ''.join(out).encode()

def do_list_themes(r):
    # triggers an extra terminal query as reference when tty+theme auto
    try:
        if r.is_tty and (r.parsed.get_last('theme',None) in (None,'','auto','auto:always')):
            _query_cache['done']=False; query_terminal_scheme(force_again=True)
    except Exception: pass
    def gen(w):
        if not r.colored:
            for t in THEMES: w.write((t+'\n').encode())
        else:
            sample="""  // Output the square of a number.
  fn print_square(num: f64) {
      let result = f64::powf(num, 2.0);
      println!("The square of {num:.2} is {result:.2}.");
  }
"""
            for t in THEMES:
                label=t
                if t=='Monokai Extended': label+=' (default)'
                if t=='Monokai Extended Light': label+=' (default light)'
                w.write((f"\x1b[1m{label}\x1b[0m\n\n").encode())
                # highlight sample in theme t
                r2=r; 
                theme=Theme(t,r.truecolor,r.parsed.get_last('italic-text','never')=='always')
                hl=Highlighter('Rust',theme)
                for line in sample.splitlines():
                    s=''
                    for slot,txt in hl.highlight(line):
                        pref=theme.prefix(slot); s+=(pref+txt+'\x1b[0m' if pref else txt)
                    w.write((s+'\n').encode())
                w.write(b'\n')
    output_via_pager(r,['STDIN'],gen)
    return 0

# ---------- diagnostic ----------
def do_diagnostic(r, prog_argv):
    import platform
    out=[]
    out.append('#### Software version\n\n')
    out.append(BAT_VERSION+'\n\n')
    out.append('#### Operating system\n\n')
    osname='Linux'; osver=''
    try:
        data=open('/etc/os-release').read(); d={}
        for line in data.splitlines():
            if '=' in line:
                k,v=line.split('=',1); d[k]=v.strip().strip('"')
        if d.get('NAME'): osver=f"{d.get('NAME')} {d.get('VERSION_ID','')}".strip()
    except Exception: pass
    out.append(f"- OS: {osname} ({osver})\n" if osver else f"- OS: {osname}\n")
    try: kern=os.uname().release
    except Exception: kern=''
    out.append(f"- Kernel: {kern}\n\n")
    out.append('#### Command-line\n\n```bash\n')
    cmd=''.join(shell_escape(a)+' ' for a in prog_argv)
    out.append(cmd+'\n```\n\n')
    out.append('#### Environment variables\n\n```bash\n')
    vars_list=['BAT_CACHE_PATH','BAT_CONFIG_PATH','BAT_OPTS','BAT_PAGER','BAT_PAGING','BAT_STYLE','BAT_TABS','BAT_THEME','BAT_WIDTH','BAT_THEME_DARK','BAT_THEME_LIGHT','COLORTERM','LANG','LC_ALL','LESS','MANPAGER','NO_COLOR','PAGER','SHELL','TERM','XDG_CACHE_HOME','XDG_CONFIG_HOME']
    for v in vars_list:
        if v in os.environ: out.append(f"{v}={shell_escape(os.environ[v])}\n")
        else: out.append(f"{v}=<not set>\n")
    out.append('```\n\n')
    def file_section(title,path):
        out.append(f'#### {title}\n\n')
        try:
            txt=open(path,'r',encoding='utf-8').read()
            out.append('```\n'+txt)
            if not txt.endswith('\n'): out.append('\n')
            out.append('```\n\n')
        except OSError as e:
            out.append(f"Could not read contents of '{path}': {os.strerror(e.errno)} (os error {e.errno}).\n\n")
    file_section('System Config file','/etc/bat/config')
    file_section('Config file',config_file_path())
    file_section('Custom assets metadata',os.path.join(cache_dir_path(),'metadata.yaml'))
    out.append('#### Custom assets\n\n')
    cache=cache_dir_path()
    if not os.path.exists(cache):
        out.append(f"'{cache}' not found\n\n")
    else:
        try:
            entries=sorted(os.listdir(cache))
            for e in entries:
                p=os.path.join(cache,e)
                if os.path.isdir(p): out.append(f"- {e}/\n")
                else:
                    try: sz=os.path.getsize(p)
                    except: sz=0
                    out.append(f"- {e}, {sz} bytes\n")
            out.append('\n')
        except Exception as e:
            out.append(f"{e}\n\n")
    out.append('#### Detected terminal color scheme\n\n')
    out.append((r.scheme if getattr(r,'scheme',None) else 'not detected')+'\n\n')
    out.append('#### Compile time information\n\n')
    out.append('- Profile: release\n- Target triple: x86_64-unknown-linux-gnu\n- Family: unix\n- OS: linux\n- Architecture: x86_64\n- Pointer width: 64\n- Endian: little\n- CPU features: fxsr,sse,sse2\n- Host: x86_64-unknown-linux-gnu\n\n')
    out.append('#### Less version\n')
    # pager binary to run --version on (ignore 'builtin')
    parsed=r.parsed; cmd='less'
    pager_occs=[o for o in parsed.occ if o.id=='pager']
    if pager_occs and pager_occs[-1].value.strip() and pager_occs[-1].value.strip()!='builtin':
        try: cmd=shell_split(pager_occs[-1].value)[0]
        except Exception: cmd='less'
    elif 'BAT_PAGER' in os.environ and os.environ['BAT_PAGER'].strip():
        try: cmd=shell_split(os.environ['BAT_PAGER'])[0]
        except Exception: pass
    elif os.environ.get('PAGER'):
        try: cmd=shell_split(os.environ['PAGER'])[0]
        except Exception: pass
    try:
        p=subprocess.run([cmd,'--version'],capture_output=True,timeout=5)
        ver=p.stdout+p.stderr
        out.append(f"\n```\n> {cmd} --version \n")
        out.append(ver.decode(errors='replace'))
        out.append('```\n\n\n')
    except OSError as e:
        out.append(f"\nCould not run command '{cmd}': {os.strerror(e.errno)} (os error {e.errno})\n\n\n")
    except Exception as e:
        out.append(f"\nCould not run command '{cmd}': {e}\n\n\n")
    sys.stdout.write(''.join(out))
    return 0

# ---------- generate config ----------
def do_generate_config():
    path=config_file_path()
    if os.path.exists(path):
        sys.stdout.write(f"A config file already exists at: {path}\nOverwrite? (y/N): "); sys.stdout.flush()
        try:
            ans=sys.stdin.readline()
        except Exception: ans=''
        if not ans or ans.strip().lower() not in ('y','yes'):
            return 0
    try:
        d=os.path.dirname(path)
        if d: os.makedirs(d,exist_ok=True)
        with open(path,'wb') as f: f.write(CONFIG_TEMPLATE)
    except OSError as e:
        raise BatFatal(f"{os.strerror(e.errno)} (os error {e.errno})")
    sys.stdout.write(f"Success! Config file written to {path}\n")
    return 0

# ---------- cache subcommand ----------
def run_cache(tokens, prog):
    parser=Parser(CACHE_SPECS,prog,is_cache=True,conflicts=CACHE_CONFLICTS)
    try:
        parsed=parser.parse(tokens)
    except CacheHelpAction as h:
        tmpl=CACHE_HELP_LONG_TMPL if h.long else CACHE_HELP_SHORT_TMPL
        sys.stdout.write(tmpl.decode().replace('{prog}',prog)); return 0
    except ClapError as e:
        if e.kind=='cache_noargs':
            sys.stderr.write(CACHE_HELP_SHORT_TMPL.decode().replace('{prog}',prog)); return 2
        raise
    import cachecmd
    return cachecmd.run(parsed, config_dir, cache_dir_path)

# ---------- main run ----------
def run(argv):
    prog=os.path.basename(argv[0]) if argv and argv[0] else 'bat'
    original_cli=list(argv[1:])
    # cache candidate from original CLI
    if original_cli and original_cli[0]=='cache' and not os.path.exists('cache'):
        return run_cache([Token(t,'cli') for t in original_cli[1:]], prog)
    # help/version candidate detection (raw token scan)
    has_help_candidate=any(t in ('-h','--help') or (t.startswith('-') and not t.startswith('--') and 'h' in t[1:]) for t in original_cli)
    has_version_candidate=any(t in ('-V','--version') or (t.startswith('-') and not t.startswith('--') and 'V' in t[1:]) for t in original_cli)
    parser=Parser(MAIN_SPECS,prog,is_cache=False,conflicts=MAIN_CONFLICTS)
    prelim=None; prelim_help_kind=None
    if has_help_candidate or has_version_candidate:
        # may raise VersionAction / ClapError
        prelim=parser.parse([Token(t,'cli') for t in original_cli])
        prelim_help_kind=prelim.help_kind
        if prelim_help_kind is None and not has_version_candidate:
            prelim=None
    no_config=('--no-config' in original_cli)
    # If prelim help: try merged best effort
    parsed=None
    if prelim is not None and prelim_help_kind is not None:
        try:
            cfg_toks=load_config_tokens(no_config)
            merged=cfg_toks+env_tokens()+[Token(t,'cli') for t in original_cli]
            parsed=parser.parse(merged)
            # if merged help kind differs, force prelim kind
            parsed.help_kind=prelim_help_kind
        except VersionAction:
            parsed=prelim
        except Exception:
            parsed=prelim
    else:
        cfg_toks=load_config_tokens(no_config)
        merged=cfg_toks+env_tokens()+[Token(t,'cli') for t in original_cli]
        if merged and merged[0].text=='cache' and not os.path.exists('cache'):
            return run_cache(merged[1:], prog)
        parsed=parser.parse(merged)
        if parsed.help_kind is not None and prelim_help_kind is None:
            # help only from config/batopts -> short
            parsed.help_kind='short'
    # file-name count check done in normal print path after resolving config? Reference errors before theme query? will check later.
    # completion handled before theme query/config resolution
    if parsed.has('completion'):
        shell=parsed.get_last('completion')
        sys.stdout.write(COMPLETIONS.get(shell,''))
        return 0
    r=resolve_config(parsed,prog,original_cli)
    # custom assets check for most modes except some trivial path printers? Reference checks even for --config-file? We'll check for print/list/help/ack modes below as needed.
    if parsed.help_kind is not None:
        # help uses assets; check
        check_custom_assets()
        return do_help(r, parsed.help_kind)
    if parsed.has('diagnostic'):
        return do_diagnostic(r, argv)
    if parsed.has('list-languages'):
        check_custom_assets(); return do_list_languages(r)
    if parsed.has('list-themes'):
        check_custom_assets(); return do_list_themes(r)
    if parsed.has('config-file'):
        sys.stdout.write(config_file_path()+'\n'); return 0
    if parsed.has('generate-config-file'):
        return do_generate_config()
    if parsed.has('config-dir'):
        sys.stdout.write(config_dir()+'\n'); return 0
    if parsed.has('cache-dir'):
        sys.stdout.write(cache_dir_path()+'\n'); return 0
    if parsed.has('acknowledgements'):
        check_custom_assets()
        # custom acknowledgements.bin handling later
        sys.stdout.buffer.write(ACKNOWLEDGEMENTS); return 0
    # normal printing
    check_custom_assets()
    # build inputs
    files=parsed.files
    file_names=parsed.get_all('file-name')
    inputs=[]
    if not files:
        inputs=[InputSpec('stdin')]
    else:
        for f in files:
            if f=='-': inputs.append(InputSpec('stdin'))
            else: inputs.append(InputSpec('file',path=f))
    if file_names:
        if len(file_names)!=len(inputs):
            raise BatFatal('Must be one file name per input type.')
        for inp,fn in zip(inputs,file_names): inp.title=fn
    # titles for terminal title
    titles=[]
    for inp in inputs:
        if inp.kind=='stdin' and inp.title is None: titles.append('STDIN')
        else: titles.append(inp.display_name())
    printcfg=make_print_config(r)
    pager=open_pager(r,titles)
    writer=Writer(pager.fp)
    ctl=Controller(printcfg,writer)
    try:
        code=ctl.run(inputs)
    finally:
        pager.close()
    return code

def main():
    argv=sys.argv
    try:
        code=run(argv)
    except VersionAction:
        sys.stdout.write(BAT_VERSION+'\n'); code=0
    except ClapError as e:
        if e.kind=='cache_noargs':
            # handled in run_cache normally
            code=2
        else:
            text=e.text
            # clap tty coloring (approximation)
            try:
                if sys.stderr.isatty() and os.environ.get('TERM') not in (None,'','dumb') and not (os.environ.get('NO_COLOR')):
                    text=colorize_clap_error(text)
            except Exception: pass
            sys.stderr.write(text); code=2
    except (BatFatal,FatalError) as e:
        sys.stderr.write(f"\x1b[31m[bat error]\x1b[0m: {e}\n"); code=1
    except BrokenPipeError:
        try:
            devnull=os.open(os.devnull,os.O_WRONLY); os.dup2(devnull,1)
        except Exception: pass
        code=0
    sys.exit(code)

def colorize_clap_error(text):
    # Apply clap-like colors used in reference for tty
    import re
    text=text.replace('error:', '\x1b[1m\x1b[31merror:\x1b[0m',1)
    text=re.sub(r'(?m)^Usage:', '\x1b[1m\x1b[4mUsage:\x1b[0m', text)
    # bold program name in usage lines is complex; skip detailed for now
    return text

if __name__=='__main__':
    main()
