import os, sys, time, json, glob
# Own cache format: store source file contents/metadata in bins as JSON compressed.
# This is not byte-compatible with syntect bincode, but preserves external build/clear messages and allows our own loader.
import zlib
VERSION='0.26.1'
def _find_files(src, sub, pattern):
    d=os.path.join(src,sub)
    if not os.path.isdir(d): return []
    out=[]
    for root,dirs,files in os.walk(d):
        for f in files:
            if f.endswith(pattern): out.append(os.path.join(root,f))
    return sorted(out)
def build(src,dest,blank,ack):
    themes=_find_files(src,'themes','.tmTheme')
    syntaxes=_find_files(src,'syntaxes','.sublime-syntax')
    # Messages for missing custom source dirs/files: reference prints when source subdirs missing/empty? It prints when no files found in an explicitly given source? For default empty dirs it did not. We approximate: if subdir doesn't exist, print message.
    if not os.path.isdir(os.path.join(src,'themes')):
        print(f"No themes were found in '{os.path.join(src,'themes')}', using the default set")
    if not os.path.isdir(os.path.join(src,'syntaxes')):
        print(f"No syntaxes were found in '{os.path.join(src,'syntaxes')}', using the default set.")
    try:
        os.makedirs(dest,exist_ok=True)
    except OSError as e:
        sys.stderr.write(f"\x1b[31m[bat error]\x1b[0m: {e}\n"); return 1
    def write_bin(name, payload):
        path=os.path.join(dest,name)
        data=zlib.compress(json.dumps(payload).encode(),9)
        with open(path,'wb') as f: f.write(data)
        print(f"Writing {'theme set' if name=='themes.bin' else 'syntax set' if name=='syntaxes.bin' else name} to {path} ... okay")
    def payload_for(files):
        out=[]
        for p in files:
            try: out.append({'path':os.path.basename(p),'text':open(p,'r',encoding='utf-8',errors='replace').read()})
            except Exception: pass
        return {'blank':blank,'files':out}
    # Order: themes, syntaxes, acknowledgements, metadata
    path=os.path.join(dest,'themes.bin')
    with open(path,'wb') as f: f.write(zlib.compress(json.dumps(payload_for(themes)).encode(),9))
    print(f"Writing theme set to {path} ... okay")
    path=os.path.join(dest,'syntaxes.bin')
    with open(path,'wb') as f: f.write(zlib.compress(json.dumps(payload_for(syntaxes)).encode(),9))
    print(f"Writing syntax set to {path} ... okay")
    if ack:
        path=os.path.join(dest,'acknowledgements.bin')
        # collect LICENSE files under syntaxes/themes source recursively (approx)
        acks=[]
        for root,dirs,files in os.walk(src):
            for fn in files:
                if 'LICENSE' in fn or fn in ('NOTICE','COPYING'):
                    try: acks.append({'path':os.path.relpath(os.path.join(root,fn),src),'text':open(os.path.join(root,fn),errors='replace').read()})
                    except Exception: pass
        with open(path,'wb') as f: f.write(zlib.compress(json.dumps(acks).encode(),9))
        print(f"Writing acknowledgements to {path} ... okay")
    # metadata
    print(f"Writing metadata to folder {dest} ... okay")
    now=time.time_ns(); secs=now//1000000000; nanos=now%1000000000
    with open(os.path.join(dest,'metadata.yaml'),'w') as f:
        f.write(f"bat_version: {VERSION}\ncreation_time:\n  secs_since_epoch: {secs}\n  nanos_since_epoch: {nanos}\n")
    return 0

def load(cache):
    # Populates highlight custom names/data minimally if our format present.
    # Syntax/theme parsing of sublime formats is not yet fully implemented; names are registered so listing can be extended in future.
    return None
