    for i in range(24):
        v=8+i*10; palette.append((v,v,v))
    best=0; bestd=None
    for idx,(pr,pg,pb) in enumerate(palette):
        d=(r-pr)**2+(g-pg)**2+(b-pb)**2
        if bestd is None or d<bestd: bestd=d; best=idx
    return best

def _fg_params(rgb,mode):
    if rgb is None: return []
