    if mode=='rgb': return ['38','2',str(r),str(g),str(b)]
    idx=_ansi256_from_rgb(r,g,b)
    if idx<8: return [str(30+idx)]
    if idx<16: return [str(90+idx-8)]
    return ['38','5',str(idx)]
def _bg_params(rgb,mode):
    if rgb is None: return []
    r,g,b,a=rgb
    if a==0: return []
    if mode=='rgb': return ['48','2',str(r),str(g),str(b)]
    idx=_ansi256_from_rgb(r,g,b)
    if idx<8: return [str(40+idx)]
